  border-radius: var(--radius-md);
  padding: 6px 12px;
}

.brand-title {
  font-family: var(--font-heading);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 2px;
  background: linear-gradient(135deg, #FFF 30%, var(--accent-gold) 100%);
