  font-family: var(--font-heading);
  font-size: 20px;
  font-weight: 600;
  color: #FFF;
}

/* ── Dropzone ─────────────────────────────────────────────────────────────── */
.dropzone {
  border: 2px dashed rgba(245, 158, 11, 0.4);
  background: rgba(245, 158, 11, 0.02);
  border-radius: var(--radius-md);
