  color: #FFF;
}

.candidate-meta {
  display: flex;
  gap: 8px;
  align-items: center;
}

.badge-category {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 2px 8px;
  border-radius: 4px;
  background: rgba(6, 182, 212, 0.15);
  color: var(--accent-cyan);
  border: 1px solid rgba(6, 182, 212, 0.3);
}

.candidate-id {
  font-size: 12px;
  font-family: monospace;
  color: var(--text-dim);
}

.candidate-dimensions {
  font-size: 11px;
  color: var(--text-dim);
}

.candidate-sim-box {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}

.sim-score-label {
  font-size: 18px;
  font-weight: 700;
  color: var(--accent-gold-light);
}

.sim-bar-bg {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 3px;
