  const statCatalogue = document.getElementById("stat-catalogue");
  const footerVectors = document.getElementById("footer-vectors");

  const tabButtons = document.querySelectorAll(".nav-tab");
  const tabViews = document.querySelectorAll(".tab-view");

  // Tab switching
  tabButtons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const targetId = btn.getAttribute("data-target");

      tabButtons.forEach((b) => b.classList.remove("active"));
      tabViews.forEach((v) => {
        v.classList.add("hidden");
        v.classList.remove("active");
      });

      btn.classList.add("active");
      const targetView = document.getElementById(targetId);
      if (targetView) {
        targetView.classList.remove("hidden");
        targetView.classList.add("active");
      }
    });
  });

  // Fetch initial live statistics
  async function refreshStats() {
    try {
      const res = await fetch("/api/stats");
      if (res.ok) {
        const data = await res.json();
        const formatted = `${data.total_items.toLocaleString()} Items`;
        if (statCatalogue) statCatalogue.textContent = formatted;
        if (footerVectors) footerVectors.textContent = `${data.total_items.toLocaleString()} items (512-d)`;
      }
    } catch (e) {
      console.warn("Could not fetch live stats:", e);
    }
  }
  refreshStats();

  // ── Tab 1: Visual Search Elements & Logic ────────────────────────────────
  const dropzone = document.getElementById("dropzone");
  const fileInput = document.getElementById("file-input");
  const dropzonePrompt = document.getElementById("dropzone-prompt");
  const previewContainer = document.getElementById("preview-container");
  const imagePreview = document.getElementById("image-preview");
  const btnClearImage = document.getElementById("btn-clear-image");

  const sliderTopk = document.getElementById("slider-topk");
  const valTopk = document.getElementById("val-topk");
  const sliderThreshold = document.getElementById("slider-threshold");
  const valThreshold = document.getElementById("val-threshold");

  const btnSearch = document.getElementById("btn-search");
  const searchSpinner = document.getElementById("search-spinner");
  const btnText = btnSearch ? btnSearch.querySelector(".btn-text") : null;

  const sampleGrid = document.getElementById("sample-grid");
  const telemetryTag = document.getElementById("telemetry-tag");

  const decisionBanner = document.getElementById("decision-banner");
  const decisionBadge = document.getElementById("decision-badge");
  const metricBestSim = document.getElementById("metric-best-sim");
  const metricThreshold = document.getElementById("metric-threshold");
  const metricLatency = document.getElementById("metric-latency");

  const emptyState = document.getElementById("empty-state");
  const candidatesList = document.getElementById("candidates-list");

  let currentSearchFile = null;

  // Search Controls Sync
  if (sliderTopk && valTopk) {
    sliderTopk.addEventListener("input", (e) => {
      valTopk.textContent = e.target.value;
    });
  }

  if (sliderThreshold && valThreshold) {
    sliderThreshold.addEventListener("input", (e) => {
      valThreshold.textContent = parseFloat(e.target.value).toFixed(2);
    });
  }

  // Search Dropzone events
  if (dropzone && fileInput) {
    ["dragenter", "dragover"].forEach((eventName) => {
      dropzone.addEventListener(eventName, (e) => {
        e.preventDefault();
        dropzone.classList.add("dragover");
      });
    });

    ["dragleave", "drop"].forEach((eventName) => {
      dropzone.addEventListener(eventName, (e) => {
        e.preventDefault();
        dropzone.classList.remove("dragover");
      });
    });

    dropzone.addEventListener("drop", (e) => {
      const files = e.dataTransfer.files;
      if (files && files.length > 0) {
        handleSearchFile(files[0]);
      }
    });

    fileInput.addEventListener("change", (e) => {
      if (e.target.files && e.target.files.length > 0) {
        handleSearchFile(e.target.files[0]);
      }
    });
  }

  function handleSearchFile(file) {
    if (!file.type.startsWith("image/")) {
      alert("Please upload a valid image file (JPEG, PNG, WebP).");
      return;
    }
    currentSearchFile = file;
    const reader = new FileReader();
    reader.onload = (event) => {
      imagePreview.src = event.target.result;
      dropzonePrompt.classList.add("hidden");
      previewContainer.classList.remove("hidden");
      btnSearch.disabled = false;
    };
    reader.readAsDataURL(file);
  }

  if (btnClearImage) {
    btnClearImage.addEventListener("click", (e) => {
      e.stopPropagation();
      currentSearchFile = null;
      fileInput.value = "";
      imagePreview.src = "";
      previewContainer.classList.add("hidden");
      dropzonePrompt.classList.remove("hidden");
      btnSearch.disabled = true;
      resetResults();
    });
  }

  // Load Catalogue Samples
  async function loadSamples() {
    if (!sampleGrid) return;
    try {
      const res = await fetch("/api/samples");
      if (!res.ok) throw new Error("Failed to load samples");
      const samples = await res.json();

      sampleGrid.innerHTML = "";
      samples.forEach((sample) => {
        const card = document.createElement("div");
        card.className = "sample-card";
        card.innerHTML = `
          <img src="${sample.image_path}" alt="${sample.product_name}" loading="lazy">
          <span class="sample-card-label">${sample.category}</span>
        `;
        card.addEventListener("click", async () => {
          try {
            const imgRes = await fetch(sample.image_path);
            const blob = await imgRes.blob();
            const file = new File([blob], `${sample.product_id}.jpg`, { type: "image/jpeg" });
            handleSearchFile(file);
            executeSearch();
          } catch (err) {
            console.error("Error loading sample:", err);
          }
        });
        sampleGrid.appendChild(card);
      });
    } catch (err) {
      sampleGrid.innerHTML = `<div class="sample-loading">Failed to load samples: ${err.message}</div>`;
    }
  }
  loadSamples();

  // Search Execution
  if (btnSearch) {
    btnSearch.addEventListener("click", () => {
      executeSearch();
    });
  }

  async function executeSearch() {
    if (!currentSearchFile) return;

    btnSearch.disabled = true;
    if (searchSpinner) searchSpinner.classList.remove("hidden");
    if (btnText) btnText.textContent = "Matching...";
    if (telemetryTag) telemetryTag.textContent = "Processing query...";

    const formData = new FormData();
    formData.append("file", currentSearchFile);
    formData.append("top_k", sliderTopk.value);
    formData.append("threshold", sliderThreshold.value);

    try {
      const response = await fetch("/api/match", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errData = await response.json().catch(() => ({ detail: response.statusText }));
        throw new Error(errData.detail || "Query matching failed.");
      }

      const data = await response.json();
      renderResults(data);
    } catch (err) {
      alert(`Search error: ${err.message}`);
      if (telemetryTag) telemetryTag.textContent = "Query failed";
    } finally {
      btnSearch.disabled = false;
      if (searchSpinner) searchSpinner.classList.add("hidden");
      if (btnText) btnText.textContent = "Search Catalogue";
    }
  }

  function renderResults(data) {
    emptyState.classList.add("hidden");
    decisionBanner.classList.remove("hidden");
    candidatesList.classList.remove("hidden");

    if (telemetryTag) {
      telemetryTag.textContent = `Completed in ${data.query_time_ms} ms (${data.top_k} results)`;
    }

    const isMatch = data.decision === "MATCH";
    decisionBadge.textContent = data.decision;
    if (isMatch) {
      decisionBanner.classList.remove("unknown");
    } else {
      decisionBanner.classList.add("unknown");
    }

    metricBestSim.textContent = data.best_similarity.toFixed(4);
    metricThreshold.textContent = data.threshold.toFixed(2);
    metricLatency.textContent = `${data.query_time_ms} ms`;

    candidatesList.innerHTML = "";
    data.results.forEach((item) => {
      const card = document.createElement("div");
      card.className = `candidate-card ${item.rank === 1 ? "top1" : ""}`;

      const simPercent = Math.max(0, Math.min(100, item.similarity * 100)).toFixed(1);
      const imgUrl = item.image_url || `/${item.image_path}`;

      card.innerHTML = `
        <div class="rank-badge">#${item.rank}</div>
        <img class="candidate-thumb" src="${imgUrl}" alt="${item.product_name}" loading="lazy">
        <div class="candidate-info">
          <div class="candidate-name">${item.product_name}</div>
          <div class="candidate-meta">
            <span class="badge-category">${item.category}</span>
            <span class="candidate-id">${item.product_id}</span>
            ${item.width ? `<span class="candidate-dimensions">${item.width}×${item.height}px</span>` : ""}
          </div>
        </div>
        <div class="candidate-sim-box">
          <div class="sim-score-label">${item.similarity.toFixed(4)}</div>
          <div class="sim-bar-bg">
            <div class="sim-bar-fill" style="width: ${simPercent}%;"></div>
          </div>
        </div>
      `;
      candidatesList.appendChild(card);
    });
  }

  function resetResults() {
    if (emptyState) emptyState.classList.remove("hidden");
    if (decisionBanner) decisionBanner.classList.add("hidden");
    if (candidatesList) {
      candidatesList.classList.add("hidden");
      candidatesList.innerHTML = "";
    }
    if (telemetryTag) telemetryTag.textContent = "Ready for query";
  }

  // ── Tab 2: Add New Catalogue Item Elements & Logic ───────────────────────
  const addDropzone = document.getElementById("add-dropzone");
  const addFileInput = document.getElementById("add-file-input");
  const addDropzonePrompt = document.getElementById("add-dropzone-prompt");
  const addPreviewContainer = document.getElementById("add-preview-container");
  const addImagePreview = document.getElementById("add-image-preview");
  const btnClearAddImage = document.getElementById("btn-clear-add-image");

  const addCategory = document.getElementById("add-category");
  const addName = document.getElementById("add-name");
  const addSubcategory = document.getElementById("add-subcategory");
  const btnAddSubmit = document.getElementById("btn-add-submit");
  const addSpinner = document.getElementById("add-spinner");
  const addTelemetryTag = document.getElementById("add-telemetry-tag");

  const addSuccessCard = document.getElementById("add-success-card");
  const addEmptyState = document.getElementById("add-empty-state");
  const addedThumb = document.getElementById("added-thumb");
  const addedTitle = document.getElementById("added-title");
  const addedCategory = document.getElementById("added-category");
  const addedId = document.getElementById("added-id");
  const addedDimensions = document.getElementById("added-dimensions");
  const btnTestInSearch = document.getElementById("btn-test-in-search");

  const recentAddedContainer = document.getElementById("recent-added-container");
  const recentList = document.getElementById("recent-list");

  let currentAddFile = null;
  let lastAddedItem = null;

  if (addDropzone && addFileInput) {
    ["dragenter", "dragover"].forEach((eventName) => {
      addDropzone.addEventListener(eventName, (e) => {
        e.preventDefault();
        addDropzone.classList.add("dragover");
      });
    });

    ["dragleave", "drop"].forEach((eventName) => {
      addDropzone.addEventListener(eventName, (e) => {
        e.preventDefault();
        addDropzone.classList.remove("dragover");
      });
    });

    addDropzone.addEventListener("drop", (e) => {
      const files = e.dataTransfer.files;
      if (files && files.length > 0) {
        handleAddFile(files[0]);
      }
    });

    addFileInput.addEventListener("change", (e) => {
      if (e.target.files && e.target.files.length > 0) {
        handleAddFile(e.target.files[0]);
      }
    });
  }

  function handleAddFile(file) {
    if (!file.type.startsWith("image/")) {
      alert("Please upload a valid image file (JPEG, PNG, WebP).");
      return;
    }
    currentAddFile = file;
    const reader = new FileReader();
    reader.onload = (event) => {
      addImagePreview.src = event.target.result;
      addDropzonePrompt.classList.add("hidden");
      addPreviewContainer.classList.remove("hidden");
      btnAddSubmit.disabled = false;
    };
    reader.readAsDataURL(file);
  }

  if (btnClearAddImage) {
    btnClearAddImage.addEventListener("click", (e) => {
      e.stopPropagation();
      currentAddFile = null;
      addFileInput.value = "";
      addImagePreview.src = "";
      addPreviewContainer.classList.add("hidden");
      addDropzonePrompt.classList.remove("hidden");
      btnAddSubmit.disabled = true;
    });
  }

  // Handle Add to Catalogue Submission
  if (btnAddSubmit) {
    btnAddSubmit.addEventListener("click", async () => {
      if (!currentAddFile) return;

      btnAddSubmit.disabled = true;
      addSpinner.classList.remove("hidden");
      const btnTextEl = btnAddSubmit.querySelector(".btn-text");
      if (btnTextEl) btnTextEl.textContent = "Processing & Indexing...";
      if (addTelemetryTag) addTelemetryTag.textContent = "Extracting CLIP vector & indexing in FAISS...";

      const formData = new FormData();
      formData.append("file", currentAddFile);
      formData.append("category", addCategory.value);
      if (addName.value.trim()) {
        formData.append("product_name", addName.value.trim());
      }
      if (addSubcategory.value.trim()) {
        formData.append("subcategory", addSubcategory.value.trim());
      }

      try {
        const response = await fetch("/api/catalogue/add", {
          method: "POST",
          body: formData,
        });

        if (!response.ok) {
          const errData = await response.json().catch(() => ({ detail: response.statusText }));
          throw new Error(errData.detail || "Failed to add item to catalogue.");
        }

        const data = await response.json();
        lastAddedItem = { ...data, fileBlob: currentAddFile };

        // Update stats
        refreshStats();
        loadSamples();

        // Render success card
        addEmptyState.classList.add("hidden");
        addSuccessCard.classList.remove("hidden");

        addedThumb.src = data.image_url;
        addedTitle.textContent = data.product_name;
        addedCategory.textContent = data.category;
        addedId.textContent = data.product_id;
        addedDimensions.textContent = `${data.width}×${data.height}px`;

        if (addTelemetryTag) {
          addTelemetryTag.textContent = `Indexed ${data.product_id} (Catalogue: ${data.catalogue_size} items)`;
        }

        // Add to session feed
        renderRecentItem(data);

        // Reset add form input
        currentAddFile = null;
        addFileInput.value = "";
        addImagePreview.src = "";
        addPreviewContainer.classList.add("hidden");
        addDropzonePrompt.classList.remove("hidden");
        addName.value = "";
        addSubcategory.value = "";

      } catch (err) {
        alert(`Error adding to catalogue: ${err.message}`);
        if (addTelemetryTag) addTelemetryTag.textContent = "Ingestion failed";
      } finally {
        btnAddSubmit.disabled = false;
        addSpinner.classList.add("hidden");
        if (btnTextEl) btnTextEl.textContent = "Add to Catalogue & Index Vector";
      }
    });
  }

  function renderRecentItem(item) {
    if (!recentAddedContainer || !recentList) return;
    recentAddedContainer.classList.remove("hidden");

    const row = document.createElement("div");
    row.className = "recent-item";
    row.innerHTML = `
      <img src="${item.image_url}" alt="${item.product_name}">
      <div class="recent-meta">
        <span class="recent-name">${item.product_name}</span>
        <div class="recent-badges">
          <span class="badge-category">${item.category}</span>
          <span class="candidate-id">${item.product_id}</span>
        </div>
      </div>
    `;
    recentList.prepend(row);
  }

  // Wire "Test Search with this Item" button
  if (btnTestInSearch) {
    btnTestInSearch.addEventListener("click", () => {
      if (!lastAddedItem) return;

      // 1. Switch tab to Search
      const searchTabBtn = document.getElementById("tab-search");
      if (searchTabBtn) searchTabBtn.click();

      // 2. Preload into search
      if (lastAddedItem.fileBlob) {
        handleSearchFile(lastAddedItem.fileBlob);
        executeSearch();
      }
    });
  }

});

/* ─────────────────────────────────────────────────────────────────────────────
   Thuli — Jewellery Image Retrieval UI Stylesheet
   Refined Minimalist Theme — Clean, Simple & Fast
   ───────────────────────────────────────────────────────────────────────────── */

:root {
  --bg-page: #0B0F19;
  --bg-card: #131B2E;
  --bg-card-subtle: rgba(255, 255, 255, 0.03);
  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-hover: rgba(245, 158, 11, 0.4);

  --text-primary: #F9FAFB;
  --text-secondary: #9CA3AF;
  --text-muted: #6B7280;

  --accent-gold: #F59E0B;
  --accent-gold-dark: #D97706;
  --accent-green: #10B981;
  --accent-red: #EF4444;
  --accent-blue: #38BDF8;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;

  --font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: var(--font-family);
  line-height: 1.5;
  min-height: 100vh;
  padding: 20px;
}

.app-layout {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── Top Header ───────────────────────────────────────────────────────────── */
.top-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand-logo {
  font-size: 24px;
}

.brand-text {
  display: flex;
  align-items: center;
  gap: 8px;
}

.brand-name {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #FFF;
}

.brand-tag {
  font-size: 11px;
  font-weight: 600;
  color: var(--accent-gold);
  background: rgba(245, 158, 11, 0.12);
  border: 1px solid rgba(245, 158, 11, 0.25);
  padding: 2px 8px;
  border-radius: 20px;
}

/* ── Tab Switcher ─────────────────────────────────────────────────────────── */
.nav-switch {
  display: flex;
  gap: 6px;
  background: rgba(0, 0, 0, 0.3);
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
}

.tab-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.tab-btn:hover {
  color: #FFF;
}

.tab-btn.active {
  background: var(--accent-gold);
  color: #0B0F19;
  font-weight: 700;
}

/* ── Grid Layout ──────────────────────────────────────────────────────────── */
.two-col-grid {
  display: grid;
  grid-template-columns: 440px 1fr;
  gap: 20px;
}

@media (max-width: 950px) {
  .two-col-grid {
    grid-template-columns: 1fr;
  }
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card-heading {
  font-size: 17px;
  font-weight: 600;
  color: #FFF;
}

.card-sub {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: -8px;
}

/* ── Dropzone ─────────────────────────────────────────────────────────────── */
.dropzone {
  border: 2px dashed rgba(255, 255, 255, 0.12);
  background: var(--bg-card-subtle);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  text-align: center;
  position: relative;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease;
  min-height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dropzone:hover, .dropzone.dragover {
  border-color: var(--accent-gold);
  background: rgba(245, 158, 11, 0.04);
}

.file-input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
  width: 100%;
  height: 100%;
}

.drop-prompt {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.drop-icon {
  font-size: 32px;
}

.drop-text {
  font-size: 14px;
  color: var(--text-secondary);
}

.drop-text strong {
  color: var(--text-primary);
}

.drop-sub {
  font-size: 11px;
  color: var(--text-muted);
}

.preview-wrap {
  position: relative;
  width: 100%;
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.preview-wrap img {
  max-width: 100%;
  max-height: 180px;
  border-radius: var(--radius-sm);
  object-fit: contain;
}

.clear-btn {
  position: absolute;
  top: -8px;
  right: -8px;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--accent-red);
  color: #FFF;
  border: none;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
}

/* ── Primary Action Button ────────────────────────────────────────────────── */
.action-btn {
  background: var(--accent-gold);
  color: #0B0F19;
  font-family: inherit;
  font-weight: 700;
  font-size: 14px;
  border: none;
  border-radius: var(--radius-sm);
  padding: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.action-btn:hover:not(:disabled) {
  opacity: 0.92;
  transform: translateY(-1px);
}

.action-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
  transform: none;
}

.spinner {
  width: 16px;
  height: 16px;
  border: 2px solid rgba(0, 0, 0, 0.2);
  border-top-color: #000;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ── Samples ──────────────────────────────────────────────────────────────── */
.samples-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px solid var(--border-subtle);
}

.samples-title {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 600;
}

.samples-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.sample-chip {
  background: var(--bg-card-subtle);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 6px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  transition: border-color 0.15s ease, transform 0.15s ease;
}

.sample-chip:hover {
  border-color: var(--accent-gold);
  transform: scale(1.04);
}

.sample-chip img {
  width: 100%;
  height: 50px;
  object-fit: contain;
  border-radius: 4px;
}

.sample-chip span {
  font-size: 10px;
  color: var(--text-secondary);
  text-transform: capitalize;
}

.samples-loading {
  font-size: 12px;
  color: var(--text-muted);
  grid-column: 1 / -1;
  text-align: center;
  padding: 6px;
}

/* ── Collapsible Settings ─────────────────────────────────────────────────── */
.settings-accordion {
  border-top: 1px solid var(--border-subtle);
  padding-top: 10px;
}

.settings-accordion summary {
  font-size: 12px;
  color: var(--text-muted);
  cursor: pointer;
  user-select: none;
  font-weight: 600;
}

.settings-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 10px;
}

.setting-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.setting-header {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--text-secondary);
}

.setting-header strong {
  color: var(--accent-gold);
}

.range-slider {
  width: 100%;
  accent-color: var(--accent-gold);
  cursor: pointer;
}

/* ── Results Area ─────────────────────────────────────────────────────────── */
.results-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.status-chip {
  font-size: 11px;
  background: var(--bg-card-subtle);
  border: 1px solid var(--border-subtle);
  padding: 3px 8px;
  border-radius: 12px;
  color: var(--text-muted);
}

/* ── Decision Banner ──────────────────────────────────────────────────────── */
.decision-box {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  background: rgba(16, 185, 129, 0.1);
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.decision-box.unknown {
  background: rgba(239, 68, 68, 0.1);
  border-color: rgba(239, 68, 68, 0.3);
}

.badge-status {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.5px;
  background: var(--accent-green);
  color: #0B0F19;
  padding: 4px 12px;
  border-radius: 4px;
}

.decision-box.unknown .badge-status {
  background: var(--accent-red);
  color: #FFF;
}

.decision-stats {
  display: flex;
  gap: 20px;
}

.stat-col {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.stat-caption {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
}

.stat-number {
  font-size: 14px;
  font-weight: 700;
  color: #FFF;
}

/* ── Empty Placeholder ────────────────────────────────────────────────────── */
.empty-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 50px 20px;
  text-align: center;
  gap: 8px;
  color: var(--text-muted);
}

.empty-glyph {
  font-size: 36px;
}

.empty-placeholder h3 {
  font-size: 15px;
  color: var(--text-secondary);
}

.empty-placeholder p {
  font-size: 12px;
  max-width: 320px;
}

/* ── Candidate Cards ──────────────────────────────────────────────────────── */
.candidates-stack {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.match-item {
  display: grid;
  grid-template-columns: 32px 70px 1fr 100px;
  align-items: center;
  gap: 12px;
  background: var(--bg-card-subtle);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  transition: border-color 0.15s ease;
}

.match-item:hover {
  border-color: var(--border-hover);
}

.match-item.top1 {
  border-color: rgba(245, 158, 11, 0.4);
  background: rgba(245, 158, 11, 0.04);
}

.rank-num {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-muted);
  text-align: center;
}

.match-item.top1 .rank-num {
  color: var(--accent-gold);
}

.match-thumb {
  width: 65px;
  height: 65px;
  object-fit: contain;
  background: rgba(0, 0, 0, 0.4);
  border-radius: 4px;
  border: 1px solid var(--border-subtle);
}

.match-details {
  display: flex;
  flex-direction: column;
  gap: 3px;
  overflow: hidden;
}

.match-title {
  font-size: 14px;
  font-weight: 600;
  color: #FFF;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.match-sub {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tag-cat {
  font-size: 10px;
  text-transform: uppercase;
  color: var(--accent-blue);
  background: rgba(56, 189, 248, 0.12);
  padding: 2px 6px;
  border-radius: 4px;
}

.tag-id {
  font-size: 11px;
  font-family: monospace;
  color: var(--text-muted);
}

.match-score {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}

.score-text {
  font-size: 15px;
  font-weight: 700;
  color: var(--accent-gold);
}

.score-track {
  width: 100%;
  height: 4px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 2px;
  overflow: hidden;
}

.score-bar {
  height: 100%;
  background: var(--accent-gold);
  border-radius: 2px;
}

/* ── Form Controls (Add Tab) ──────────────────────────────────────────────── */
.field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-group label {
  font-size: 12px;
  color: var(--text-secondary);
}

.form-control {
  width: 100%;
  padding: 10px 12px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 13px;
}

.form-control:focus {
  outline: none;
  border-color: var(--accent-gold);
}

.form-control option {
  background: #131B2E;
  color: #FFF;
}

/* ── Success Box (Add Tab) ────────────────────────────────────────────────── */
.success-box {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
  border-radius: var(--radius-sm);
  background: rgba(16, 185, 129, 0.08);
  border: 1px solid rgba(16, 185, 129, 0.25);
}

.success-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.check-glyph {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-green);
  color: #0B0F19;
  font-size: 16px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.success-headline {
  font-size: 15px;
  font-weight: 600;
  color: #FFF;
}

.success-subline {
  font-size: 12px;
  color: var(--text-secondary);
}

.new-item-row {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(0, 0, 0, 0.25);
  border-radius: 4px;
  padding: 10px;
}

.item-thumb {
  width: 60px;
  height: 60px;
  object-fit: contain;
  background: rgba(0, 0, 0, 0.4);
  border-radius: 4px;
}

.item-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.item-name {
  font-size: 14px;
  font-weight: 600;
  color: #FFF;
}

.item-tags {
  display: flex;
  gap: 6px;
}

.secondary-btn {
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.4);
  color: #FFF;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  padding: 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.15s ease;
}

.secondary-btn:hover {
  background: var(--accent-blue);
  color: #0B0F19;
}

/* ── Recent Items ─────────────────────────────────────────────────────────── */
.recent-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 10px;
}

.recent-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.recent-row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-card-subtle);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
}

.recent-row img {
  width: 36px;
  height: 36px;
  object-fit: contain;
  border-radius: 4px;
}

.recent-row span {
  font-size: 12px;
  color: var(--text-secondary);
}

/* ── Bottom Bar ───────────────────────────────────────────────────────────── */
.bottom-bar {
  text-align: center;
  font-size: 12px;
  color: var(--text-muted);
  padding: 8px;
}

.hidden {
  display: none !important;
}

/**
 * Thuli — Minimalist Jewellery Visual Search Client
 */

document.addEventListener("DOMContentLoaded", () => {
  // ── Tab Navigation ───────────────────────────────────────────────────────
  const tabButtons = document.querySelectorAll(".tab-btn");
  const tabViews = document.querySelectorAll(".view-pane");

  tabButtons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const targetId = btn.getAttribute("data-target");

      tabButtons.forEach((b) => b.classList.remove("active"));
      tabViews.forEach((v) => {
        v.classList.add("hidden");
        v.classList.remove("active");
      });

      btn.classList.add("active");
      const targetView = document.getElementById(targetId);
      if (targetView) {
        targetView.classList.remove("hidden");
        targetView.classList.add("active");
      }
    });
  });

  // Live Catalogue Size
  const statCatalogue = document.getElementById("stat-catalogue");
  async function refreshStats() {
    try {
      const res = await fetch("/api/stats");
      if (res.ok) {
        const data = await res.json();
        if (statCatalogue) {
          statCatalogue.textContent = `${data.total_items.toLocaleString()} Items`;
        }
      }
    } catch (e) {
      console.warn("Could not fetch stats:", e);
    }
  }
  refreshStats();

  // ── Tab 1: Visual Search ─────────────────────────────────────────────────
  const dropzone = document.getElementById("dropzone");
  const fileInput = document.getElementById("file-input");
  const dropzonePrompt = document.getElementById("dropzone-prompt");
  const previewContainer = document.getElementById("preview-container");
  const imagePreview = document.getElementById("image-preview");
  const btnClearImage = document.getElementById("btn-clear-image");

  const sliderTopk = document.getElementById("slider-topk");
  const valTopk = document.getElementById("val-topk");
  const sliderThreshold = document.getElementById("slider-threshold");
  const valThreshold = document.getElementById("val-threshold");

  const btnSearch = document.getElementById("btn-search");
  const searchSpinner = document.getElementById("search-spinner");
  const btnLabel = btnSearch ? btnSearch.querySelector(".btn-label") : null;

  const sampleGrid = document.getElementById("sample-grid");
  const telemetryTag = document.getElementById("telemetry-tag");

  const decisionBanner = document.getElementById("decision-banner");
  const decisionBadge = document.getElementById("decision-badge");
  const metricBestSim = document.getElementById("metric-best-sim");
  const metricLatency = document.getElementById("metric-latency");

  const emptyState = document.getElementById("empty-state");
  const candidatesList = document.getElementById("candidates-list");

  let currentSearchFile = null;

  // Sliders Sync
  if (sliderTopk && valTopk) {
    sliderTopk.addEventListener("input", (e) => {
      valTopk.textContent = e.target.value;
    });
  }

  if (sliderThreshold && valThreshold) {
    sliderThreshold.addEventListener("input", (e) => {
      valThreshold.textContent = parseFloat(e.target.value).toFixed(2);
    });
  }

  // Dropzone Handlers
  if (dropzone && fileInput) {
    ["dragenter", "dragover"].forEach((evt) => {
      dropzone.addEventListener(evt, (e) => {
        e.preventDefault();
        dropzone.classList.add("dragover");
      });
    });

    ["dragleave", "drop"].forEach((evt) => {
      dropzone.addEventListener(evt, (e) => {
        e.preventDefault();
        dropzone.classList.remove("dragover");
      });
    });

    dropzone.addEventListener("drop", (e) => {
      const files = e.dataTransfer.files;
      if (files && files.length > 0) handleSearchFile(files[0]);
    });

    fileInput.addEventListener("change", (e) => {
      if (e.target.files && e.target.files.length > 0) handleSearchFile(e.target.files[0]);
    });
  }

  function handleSearchFile(file) {
    if (!file.type.startsWith("image/")) {
      alert("Please upload a valid image (JPEG, PNG, WebP).");
      return;
    }
    currentSearchFile = file;
    const reader = new FileReader();
    reader.onload = (event) => {
      imagePreview.src = event.target.result;
      dropzonePrompt.classList.add("hidden");
      previewContainer.classList.remove("hidden");
      btnSearch.disabled = false;
    };
    reader.readAsDataURL(file);
  }

  if (btnClearImage) {
    btnClearImage.addEventListener("click", (e) => {
      e.stopPropagation();
      currentSearchFile = null;
      fileInput.value = "";
      imagePreview.src = "";
      previewContainer.classList.add("hidden");
      dropzonePrompt.classList.remove("hidden");
      btnSearch.disabled = true;
      resetResults();
    });
  }

  // Load Samples
  async function loadSamples() {
    if (!sampleGrid) return;
    try {
      const res = await fetch("/api/samples");
      if (!res.ok) throw new Error("Could not load samples");
      const samples = await res.json();

      sampleGrid.innerHTML = "";
      samples.slice(0, 4).forEach((sample) => {
        const chip = document.createElement("div");
        chip.className = "sample-chip";
        chip.innerHTML = `
          <img src="${sample.image_path}" alt="${sample.product_name}" loading="lazy">
          <span>${sample.category}</span>
        `;
        chip.addEventListener("click", async () => {
          try {
            const imgRes = await fetch(sample.image_path);
            const blob = await imgRes.blob();
            const file = new File([blob], `${sample.product_id}.jpg`, { type: "image/jpeg" });
            handleSearchFile(file);
            executeSearch();
          } catch (err) {
            console.error("Error loading sample:", err);
          }
        });
        sampleGrid.appendChild(chip);
      });
    } catch (err) {
      sampleGrid.innerHTML = `<span class="samples-loading">Samples unavailable</span>`;
    }
  }
  loadSamples();

  // Search Action
  if (btnSearch) {
    btnSearch.addEventListener("click", () => {
      executeSearch();
    });
  }

  async function executeSearch() {
    if (!currentSearchFile) return;

    btnSearch.disabled = true;
    if (searchSpinner) searchSpinner.classList.remove("hidden");
    if (btnLabel) btnLabel.textContent = "Searching...";
    if (telemetryTag) telemetryTag.textContent = "Retrieving...";

    const formData = new FormData();
    formData.append("file", currentSearchFile);
    formData.append("top_k", sliderTopk.value);
    formData.append("threshold", sliderThreshold.value);

    try {
      const response = await fetch("/api/match", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errData = await response.json().catch(() => ({ detail: response.statusText }));
        throw new Error(errData.detail || "Query matching failed.");
      }

      const data = await response.json();
      renderResults(data);
    } catch (err) {
      alert(`Search error: ${err.message}`);
      if (telemetryTag) telemetryTag.textContent = "Error";
    } finally {
      btnSearch.disabled = false;
      if (searchSpinner) searchSpinner.classList.add("hidden");
      if (btnLabel) btnLabel.textContent = "Find Matching Jewellery";
    }
  }

  function renderResults(data) {
    emptyState.classList.add("hidden");
    decisionBanner.classList.remove("hidden");
    candidatesList.classList.remove("hidden");

    if (telemetryTag) {
      telemetryTag.textContent = `${data.query_time_ms} ms (${data.top_k} results)`;
    }

    const isMatch = data.decision === "MATCH";
    decisionBadge.textContent = data.decision;
    if (isMatch) {
      decisionBanner.classList.remove("unknown");
    } else {
      decisionBanner.classList.add("unknown");
    }

    metricBestSim.textContent = `${(data.best_similarity * 100).toFixed(1)}%`;
    metricLatency.textContent = `${data.query_time_ms} ms`;

    candidatesList.innerHTML = "";
    data.results.forEach((item) => {
      const row = document.createElement("div");
      row.className = `match-item ${item.rank === 1 ? "top1" : ""}`;

      const simPercent = Math.max(0, Math.min(100, item.similarity * 100)).toFixed(1);
      const imgUrl = item.image_url || `/${item.image_path}`;

      row.innerHTML = `
        <span class="rank-num">#${item.rank}</span>
        <img class="match-thumb" src="${imgUrl}" alt="${item.product_name}" loading="lazy">
        <div class="match-details">
          <span class="match-title">${item.product_name}</span>
          <div class="match-sub">
            <span class="tag-cat">${item.category}</span>
            <span class="tag-id">${item.product_id}</span>
          </div>
        </div>
        <div class="match-score">
          <span class="score-text">${simPercent}%</span>
          <div class="score-track">
            <div class="score-bar" style="width: ${simPercent}%;"></div>
          </div>
        </div>
      `;
      candidatesList.appendChild(row);
    });
  }

  function resetResults() {
    if (emptyState) emptyState.classList.remove("hidden");
    if (decisionBanner) decisionBanner.classList.add("hidden");
    if (candidatesList) {
      candidatesList.classList.add("hidden");
      candidatesList.innerHTML = "";
    }
    if (telemetryTag) telemetryTag.textContent = "Ready";
  }

  // ── Tab 2: Add New Catalogue Item ────────────────────────────────────────
  const addDropzone = document.getElementById("add-dropzone");
  const addFileInput = document.getElementById("add-file-input");
  const addDropzonePrompt = document.getElementById("add-dropzone-prompt");
  const addPreviewContainer = document.getElementById("add-preview-container");
  const addImagePreview = document.getElementById("add-image-preview");
  const btnClearAddImage = document.getElementById("btn-clear-add-image");

  const addCategory = document.getElementById("add-category");
  const addName = document.getElementById("add-name");
  const btnAddSubmit = document.getElementById("btn-add-submit");
  const addSpinner = document.getElementById("add-spinner");
  const addTelemetryTag = document.getElementById("add-telemetry-tag");

  const addSuccessCard = document.getElementById("add-success-card");
  const addEmptyState = document.getElementById("add-empty-state");
  const addedThumb = document.getElementById("added-thumb");
  const addedTitle = document.getElementById("added-title");
  const addedCategory = document.getElementById("added-category");
  const addedId = document.getElementById("added-id");
  const btnTestInSearch = document.getElementById("btn-test-in-search");

  const recentAddedContainer = document.getElementById("recent-added-container");
  const recentList = document.getElementById("recent-list");

  let currentAddFile = null;
  let lastAddedItem = null;

  if (addDropzone && addFileInput) {
    ["dragenter", "dragover"].forEach((evt) => {
      addDropzone.addEventListener(evt, (e) => {
        e.preventDefault();
        addDropzone.classList.add("dragover");
      });
    });

    ["dragleave", "drop"].forEach((evt) => {
      addDropzone.addEventListener(evt, (e) => {
        e.preventDefault();
        addDropzone.classList.remove("dragover");
      });
    });

    addDropzone.addEventListener("drop", (e) => {
      const files = e.dataTransfer.files;
      if (files && files.length > 0) handleAddFile(files[0]);
    });

    addFileInput.addEventListener("change", (e) => {
      if (e.target.files && e.target.files.length > 0) handleAddFile(e.target.files[0]);
    });
  }

  function handleAddFile(file) {
    if (!file.type.startsWith("image/")) {
      alert("Please upload a valid image (JPEG, PNG, WebP).");
      return;
    }
    currentAddFile = file;
    const reader = new FileReader();
    reader.onload = (event) => {
      addImagePreview.src = event.target.result;
      addDropzonePrompt.classList.add("hidden");
      addPreviewContainer.classList.remove("hidden");
      btnAddSubmit.disabled = false;
    };
    reader.readAsDataURL(file);
  }

  if (btnClearAddImage) {
    btnClearAddImage.addEventListener("click", (e) => {
      e.stopPropagation();
      currentAddFile = null;
      addFileInput.value = "";
      addImagePreview.src = "";
      addPreviewContainer.classList.add("hidden");
      addDropzonePrompt.classList.remove("hidden");
      btnAddSubmit.disabled = true;
    });
  }

  if (btnAddSubmit) {
    btnAddSubmit.addEventListener("click", async () => {
      if (!currentAddFile) return;

      btnAddSubmit.disabled = true;
      if (addSpinner) addSpinner.classList.remove("hidden");
      const btnLabelEl = btnAddSubmit.querySelector(".btn-label");
      if (btnLabelEl) btnLabelEl.textContent = "Indexing...";
      if (addTelemetryTag) addTelemetryTag.textContent = "Indexing vector...";

      const formData = new FormData();
      formData.append("file", currentAddFile);
      formData.append("category", addCategory.value);
      if (addName && addName.value.trim()) {
        formData.append("product_name", addName.value.trim());
      }

      try {
        const response = await fetch("/api/catalogue/add", {
          method: "POST",
          body: formData,
        });

        if (!response.ok) {
          const errData = await response.json().catch(() => ({ detail: response.statusText }));
          throw new Error(errData.detail || "Failed to add item.");
        }

        const data = await response.json();
        lastAddedItem = { ...data, fileBlob: currentAddFile };

        refreshStats();
        loadSamples();

        addEmptyState.classList.add("hidden");
        addSuccessCard.classList.remove("hidden");

        addedThumb.src = data.image_url;
        addedTitle.textContent = data.product_name;
        addedCategory.textContent = data.category;
        addedId.textContent = data.product_id;

        if (addTelemetryTag) {
          addTelemetryTag.textContent = `Indexed ${data.product_id}`;
        }

        renderRecentRow(data);

        // Reset Add inputs
        currentAddFile = null;
        addFileInput.value = "";
        addImagePreview.src = "";
        addPreviewContainer.classList.add("hidden");
        addDropzonePrompt.classList.remove("hidden");
        if (addName) addName.value = "";

      } catch (err) {
        alert(`Error adding to catalogue: ${err.message}`);
        if (addTelemetryTag) addTelemetryTag.textContent = "Failed";
      } finally {
        btnAddSubmit.disabled = false;
        if (addSpinner) addSpinner.classList.add("hidden");
        if (btnLabelEl) btnLabelEl.textContent = "Add to Catalogue & Index";
      }
    });
  }

  function renderRecentRow(item) {
    if (!recentAddedContainer || !recentList) return;
    recentAddedContainer.classList.remove("hidden");

    const row = document.createElement("div");
    row.className = "recent-row";
    row.innerHTML = `
      <img src="${item.image_url}" alt="${item.product_name}">
      <span>${item.product_name} (${item.category} • ${item.product_id})</span>
    `;
    recentList.prepend(row);
  }

  // "Search for this Item" Button
  if (btnTestInSearch) {
    btnTestInSearch.addEventListener("click", () => {
      if (!lastAddedItem) return;

      const searchTabBtn = document.getElementById("tab-search");
      if (searchTabBtn) searchTabBtn.click();

      if (lastAddedItem.fileBlob) {
        handleSearchFile(lastAddedItem.fileBlob);
        executeSearch();
      }
    });
  }
});

