/* ═══════════════════════════════════════════════════════════════════════════
   PHASE 7 — EVALUATION ARENA STYLES
   Fighter / scoreboard aesthetic — dark + neon accent
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Arena Banner ──────────────────────────────────────────────────────────── */
.arena-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(135deg, #0d1422 0%, #131B2E 60%, #1a1040 100%);
  border: 1px solid rgba(245, 158, 11, 0.25);
  border-radius: var(--radius-lg);
  padding: 20px 28px;
  position: relative;
  overflow: hidden;
  flex-wrap: wrap;
  gap: 16px;
}

.arena-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 20px,
    rgba(245, 158, 11, 0.015) 20px,
    rgba(245, 158, 11, 0.015) 21px
  );
  pointer-events: none;
}

.arena-title-wrap {
  display: flex;
  align-items: center;
  gap: 16px;
}

.arena-icon {
  font-size: 36px;
  filter: drop-shadow(0 0 12px rgba(245, 158, 11, 0.6));
}

.arena-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--accent-gold);
  text-shadow: 0 0 20px rgba(245, 158, 11, 0.4);
  line-height: 1;
  margin-bottom: 4px;
}

.arena-sub {
  font-size: 12px;
  color: var(--text-muted);
  letter-spacing: 0.5px;
}

.arena-controls {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}

/* ── Eval Buttons ─────────────────────────────────────────────────────────── */
.eval-btn {
  font-family: var(--font-family);
  font-size: 13px;
  font-weight: 700;
  padding: 10px 18px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  border: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  transition: all 0.15s ease;
  letter-spacing: 0.3px;
}

.eval-btn-primary {
  background: var(--accent-gold);
  color: #0B0F19;
  box-shadow: 0 0 16px rgba(245, 158, 11, 0.3);
}

.eval-btn-primary:hover {
  opacity: 0.9;
  transform: translateY(-1px);
  box-shadow: 0 0 24px rgba(245, 158, 11, 0.5);
}

.eval-btn-primary:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
}

.eval-btn-ghost {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.12);
  color: var(--text-secondary);
}

.eval-btn-ghost:hover {
  background: rgba(255,255,255,0.1);
  color: #FFF;
}

/* ── Empty State ──────────────────────────────────────────────────────────── */
.eval-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 20px;
  text-align: center;
  gap: 12px;
}

.eval-empty-icon { font-size: 48px; }

.eval-empty h3 {
  font-size: 18px;
  color: var(--text-secondary);
}

.eval-empty p {
  font-size: 13px;
  color: var(--text-muted);
  max-width: 360px;
}

/* ── Scoreboard ───────────────────────────────────────────────────────────── */
.scoreboard {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}

@media (max-width: 1100px) {
  .scoreboard { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 700px) {
  .scoreboard { grid-template-columns: repeat(2, 1fr); }
}

.score-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 18px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  border: 1px solid var(--border-subtle);
  position: relative;
  overflow: hidden;
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.score-card:hover {
  transform: translateY(-2px);
}

.score-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  border-radius: 3px 3px 0 0;
}

.score-card--gold::before   { background: var(--accent-gold); box-shadow: 0 0 10px rgba(245,158,11,0.6); }
.score-card--blue::before   { background: var(--accent-blue); box-shadow: 0 0 10px rgba(56,189,248,0.6); }
.score-card--green::before  { background: var(--accent-green); box-shadow: 0 0 10px rgba(16,185,129,0.6); }
.score-card--red::before    { background: var(--accent-red); box-shadow: 0 0 10px rgba(239,68,68,0.6); }
.score-card--purple::before { background: #a78bfa; box-shadow: 0 0 10px rgba(167,139,250,0.6); }
.score-card--orange::before { background: #fb923c; box-shadow: 0 0 10px rgba(251,146,60,0.6); }

.score-card--gold   { border-color: rgba(245,158,11,0.3); }
.score-card--blue   { border-color: rgba(56,189,248,0.3); }
.score-card--green  { border-color: rgba(16,185,129,0.3); }
.score-card--red    { border-color: rgba(239,68,68,0.3); }
.score-card--purple { border-color: rgba(167,139,250,0.3); }
.score-card--orange { border-color: rgba(251,146,60,0.3); }

.score-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  text-transform: uppercase;
}

.score-value {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 28px;
  font-weight: 700;
  color: #FFF;
  line-height: 1.1;
}

.score-card--gold   .score-value { color: var(--accent-gold); }
.score-card--blue   .score-value { color: var(--accent-blue); }
.score-card--green  .score-value { color: var(--accent-green); }
.score-card--red    .score-value { color: var(--accent-red); }
.score-card--purple .score-value { color: #a78bfa; }
.score-card--orange .score-value { color: #fb923c; }

.score-sublabel {
  font-size: 10px;
  color: var(--text-muted);
}

/* ── Mid grid ─────────────────────────────────────────────────────────────── */
.eval-mid-grid {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 14px;
}

@media (max-width: 900px) {
  .eval-mid-grid { grid-template-columns: 1fr; }
}

.eval-card { gap: 14px; }

/* ── Condition Accuracy Chart ─────────────────────────────────────────────── */
.condition-chart {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.cond-row {
  display: grid;
  grid-template-columns: 130px 1fr 52px 52px;
  align-items: center;
  gap: 10px;
}

.cond-name {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cond-bar-track {
  background: rgba(255,255,255,0.06);
  border-radius: 4px;
  height: 10px;
  overflow: hidden;
  position: relative;
}

.cond-bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.cond-bar-fill--top1 {
  background: linear-gradient(90deg, var(--accent-gold), #fbbf24);
}

.cond-bar-fill--top5 {
  background: linear-gradient(90deg, var(--accent-blue), #7dd3fc);
  opacity: 0.55;
}

.cond-pct {
  font-size: 11px;
  font-weight: 700;
  text-align: right;
}

.cond-pct--top1 { color: var(--accent-gold); }
.cond-pct--top5 { color: var(--accent-blue); }

.chart-legend {
  display: flex;
  gap: 16px;
  margin-bottom: 4px;
}

.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  display: inline-block;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: var(--text-muted);
}

/* ── Dataset Progress ─────────────────────────────────────────────────────── */
.progress-arena {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.progress-numbers {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.prog-current {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 40px;
  font-weight: 700;
  color: var(--accent-gold);
  line-height: 1;
}

.prog-sep {
  font-size: 24px;
  color: var(--text-muted);
}

.prog-target {
  font-size: 20px;
  color: var(--text-muted);
}

.progress-track {
  background: rgba(255,255,255,0.06);
  border-radius: 6px;
  height: 14px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-gold), #fbbf24);
  border-radius: 6px;
  transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 0 10px rgba(245,158,11,0.4);
}

.progress-pct {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-gold);
}

.progress-hint {
  font-size: 11px;
  color: var(--text-muted);
}

.verdict-split {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}

.verdict-track {
  flex: 1;
  display: flex;
  height: 10px;
  border-radius: 5px;
  overflow: hidden;
}

.verdict-match-bar {
  background: var(--accent-green);
  height: 100%;
  transition: width 0.6s ease;
}

.verdict-unknown-bar {
  background: var(--accent-red);
  height: 100%;
  transition: width 0.6s ease;
}

.verdict-label {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
}

.verdict-count {
  font-weight: 700;
  color: var(--text-primary);
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}

.dot--green { background: var(--accent-green); }
.dot--red   { background: var(--accent-red); }

/* ── Failures Table ───────────────────────────────────────────────────────── */
.failures-table-wrap {
  overflow-x: auto;
}

.failures-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.failures-table th {
  text-align: left;
  padding: 10px 12px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  border-bottom: 1px solid var(--border-subtle);
  white-space: nowrap;
}

.failures-table td {
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  color: var(--text-secondary);
  vertical-align: middle;
}

.failures-table tr:hover td {
  background: rgba(255,255,255,0.02);
}

.failure-thumb {
  width: 44px;
  height: 44px;
  object-fit: cover;
  border-radius: 6px;
  border: 1px solid var(--border-subtle);
  background: rgba(0,0,0,0.4);
}

.tag-condition {
  font-size: 10px;
  background: rgba(167,139,250,0.12);
  border: 1px solid rgba(167,139,250,0.25);
  color: #a78bfa;
  padding: 2px 6px;
  border-radius: 4px;
  white-space: nowrap;
}

.badge-match {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  background: rgba(16,185,129,0.15);
  border: 1px solid rgba(16,185,129,0.3);
  color: var(--accent-green);
}

.badge-unknown {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  background: rgba(239,68,68,0.15);
  border: 1px solid rgba(239,68,68,0.3);
  color: var(--accent-red);
}

.sim-low  { color: var(--accent-red); font-weight: 700; }
.sim-mid  { color: #fb923c; font-weight: 700; }
.sim-high { color: var(--accent-green); font-weight: 700; }

.table-empty {
  text-align: center;
  padding: 30px;
  color: var(--text-muted);
}

/* ── Eval Meta ────────────────────────────────────────────────────────────── */
.eval-meta {
  text-align: center;
  font-size: 11px;
  color: var(--text-muted);
  padding: 4px;
}

/* ── Eval content layout ──────────────────────────────────────────────────── */
.eval-content {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.view-pane {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

