/* ─────────────────────────────────────────────────────────────────────────────
   Thuli — Jewellery Retrieval System
   Light Theme — Clean, Crisp, Premium
   ───────────────────────────────────────────────────────────────────────────── */

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');

:root {
  /* Light theme palette */
  --bg-page:          #F4F6FA;
  --bg-card:          #FFFFFF;
  --bg-card-subtle:   #F8F9FB;
  --bg-hover:         #F0F2F7;

  --border:           #E2E6EF;
  --border-hover:     #C8A84B;

  --text-primary:     #0F1623;
  --text-secondary:   #4B5563;
  --text-muted:       #9CA3AF;

  --accent-gold:      #C8912A;
  --accent-gold-bg:   rgba(200, 145, 42, 0.10);
  --accent-gold-dark: #A67520;
  --accent-green:     #059669;
  --accent-green-bg:  rgba(5, 150, 105, 0.08);
  --accent-red:       #DC2626;
  --accent-red-bg:    rgba(220, 38, 38, 0.08);
  --accent-blue:      #2563EB;
  --accent-blue-bg:   rgba(37, 99, 235, 0.08);
  --accent-purple:    #7C3AED;
  --accent-orange:    #EA580C;

  --shadow-sm:  0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md:  0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg:  0 8px 24px rgba(0,0,0,0.10), 0 4px 8px rgba(0,0,0,0.04);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;

  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-mono: 'Space Grotesk', monospace;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

/* ── App Layout ────────────────────────────────────────────────────────────── */
.app-layout {
  max-width: 1280px;
  margin: 0 auto;
  padding: 16px 20px 40px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── Top Navigation ────────────────────────────────────────────────────────── */
.top-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  flex-wrap: wrap;
  gap: 12px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand-logo { font-size: 22px; }

.brand-name {
  font-family: var(--font-mono);
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--text-primary);
}

.brand-tag {
  font-size: 11px;
  font-weight: 600;
  color: var(--accent-gold-dark);
  background: var(--accent-gold-bg);
  border: 1px solid rgba(200, 145, 42, 0.25);
  padding: 2px 8px;
  border-radius: 20px;
}

/* ── Tab Navigation ────────────────────────────────────────────────────────── */
.nav-switch {
  display: flex;
  gap: 4px;
  background: var(--bg-page);
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}

.tab-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 600;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.tab-btn:hover { color: var(--text-primary); background: var(--bg-card); }

.tab-btn.active {
  background: var(--accent-gold);
  color: #FFF;
  font-weight: 700;
  box-shadow: 0 2px 8px rgba(200, 145, 42, 0.35);
}

/* ── View Pane ─────────────────────────────────────────────────────────────── */
.view-pane {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.view-pane.hidden { display: none; }

/* ── Card ──────────────────────────────────────────────────────────────────── */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: var(--shadow-sm);
}

.card-heading {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
}

.card-sub {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: -8px;
}

/* ── Grid ──────────────────────────────────────────────────────────────────── */
.two-col-grid {
  display: grid;
  grid-template-columns: 400px 1fr;
  gap: 16px;
}

@media (max-width: 900px) {
  .two-col-grid { grid-template-columns: 1fr; }
}

/* ── Dropzone ──────────────────────────────────────────────────────────────── */
.dropzone {
  border: 2px dashed var(--border);
  background: var(--bg-card-subtle);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  position: relative;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
  min-height: 170px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dropzone:hover, .dropzone.dragover {
  border-color: var(--accent-gold);
  background: var(--accent-gold-bg);
}

.file-input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
  width: 100%;
  height: 100%;
}

.drop-prompt {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
}

.drop-icon { font-size: 30px; }

.drop-text {
  font-size: 14px;
  color: var(--text-secondary);
}

.drop-text strong { color: var(--text-primary); }

.drop-sub {
  font-size: 11px;
  color: var(--text-muted);
}

.preview-wrap {
  position: relative;
  width: 100%;
  height: 170px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.preview-wrap img {
  max-width: 100%;
  max-height: 170px;
  border-radius: var(--radius-sm);
  object-fit: contain;
}

.clear-btn {
  position: absolute;
  top: -8px;
  right: -8px;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--accent-red);
  color: #FFF;
  border: none;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  box-shadow: var(--shadow-sm);
}

/* ── Action Button ─────────────────────────────────────────────────────────── */
.action-btn {
  background: var(--accent-gold);
  color: #FFF;
  font-family: var(--font-sans);
  font-weight: 700;
  font-size: 14px;
  border: none;
  border-radius: var(--radius-sm);
  padding: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.15s ease;
  box-shadow: 0 2px 8px rgba(200, 145, 42, 0.3);
}

.action-btn:hover:not(:disabled) {
  background: var(--accent-gold-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(200, 145, 42, 0.4);
}

.action-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

.spinner {
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255,255,255,0.3);
  border-top-color: #FFF;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
  flex-shrink: 0;
}

@keyframes spin { to { transform: rotate(360deg); } }

/* ── Samples ───────────────────────────────────────────────────────────────── */
.samples-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px solid var(--border);
}

.samples-title {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.samples-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.sample-chip {
  background: var(--bg-card-subtle);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 6px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  transition: all 0.15s ease;
}

.sample-chip:hover {
  border-color: var(--accent-gold);
  background: var(--accent-gold-bg);
  transform: scale(1.03);
}

.sample-chip img {
  width: 100%;
  height: 50px;
  object-fit: contain;
  border-radius: 4px;
}

.sample-chip span {
  font-size: 10px;
  color: var(--text-secondary);
  text-transform: capitalize;
}

.samples-loading {
  font-size: 12px;
  color: var(--text-muted);
  grid-column: 1 / -1;
  text-align: center;
  padding: 6px;
}

/* ── Settings Accordion ────────────────────────────────────────────────────── */
.settings-accordion {
  border-top: 1px solid var(--border);
  padding-top: 10px;
}

.settings-accordion summary {
  font-size: 12px;
  color: var(--text-muted);
  cursor: pointer;
  user-select: none;
  font-weight: 600;
}

.settings-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 10px;
}

.setting-item { display: flex; flex-direction: column; gap: 4px; }

.setting-header {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--text-secondary);
}

.setting-header strong { color: var(--accent-gold-dark); font-weight: 700; }

.range-slider {
  width: 100%;
  accent-color: var(--accent-gold);
  cursor: pointer;
}

/* ── Results Area ──────────────────────────────────────────────────────────── */
.results-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.status-chip {
  font-size: 11px;
  background: var(--bg-card-subtle);
  border: 1px solid var(--border);
  padding: 3px 10px;
  border-radius: 12px;
  color: var(--text-muted);
}

/* ── Decision Banner ───────────────────────────────────────────────────────── */
.decision-box {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  background: var(--accent-green-bg);
  border: 1px solid rgba(5, 150, 105, 0.2);
}

.decision-box.unknown {
  background: var(--accent-red-bg);
  border-color: rgba(220, 38, 38, 0.2);
}

.badge-status {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.5px;
  background: var(--accent-green);
  color: #FFF;
  padding: 4px 12px;
  border-radius: 6px;
}

.decision-box.unknown .badge-status { background: var(--accent-red); }

.decision-stats { display: flex; gap: 20px; }

.stat-col { display: flex; flex-direction: column; align-items: flex-end; }

.stat-caption {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.stat-number {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
}

/* ── Empty Placeholder ─────────────────────────────────────────────────────── */
.empty-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 50px 20px;
  text-align: center;
  gap: 8px;
  color: var(--text-muted);
}

.empty-glyph { font-size: 36px; }

.empty-placeholder h3 {
  font-size: 15px;
  color: var(--text-secondary);
  font-weight: 600;
}

.empty-placeholder p {
  font-size: 12px;
  max-width: 320px;
  color: var(--text-muted);
}

/* ── Candidate Cards ───────────────────────────────────────────────────────── */
.candidates-stack { display: flex; flex-direction: column; gap: 10px; }

.match-item {
  display: grid;
  grid-template-columns: 28px 68px 1fr 96px;
  align-items: center;
  gap: 12px;
  background: var(--bg-card-subtle);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  transition: all 0.15s ease;
}

.match-item:hover {
  border-color: var(--accent-gold);
  background: var(--accent-gold-bg);
}

.match-item.top1 {
  border-color: rgba(200, 145, 42, 0.5);
  background: var(--accent-gold-bg);
}

.rank-num {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-muted);
  text-align: center;
}

.match-item.top1 .rank-num { color: var(--accent-gold-dark); }

.match-thumb {
  width: 64px;
  height: 64px;
  object-fit: contain;
  background: var(--bg-page);
  border-radius: 6px;
  border: 1px solid var(--border);
}

.match-details {
  display: flex;
  flex-direction: column;
  gap: 3px;
  overflow: hidden;
}

.match-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.match-sub {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tag-cat {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--accent-blue);
  background: var(--accent-blue-bg);
  border: 1px solid rgba(37, 99, 235, 0.2);
  padding: 2px 6px;
  border-radius: 4px;
}

.tag-id {
  font-size: 11px;
  font-family: monospace;
  color: var(--text-muted);
}

.match-score {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
}

.score-text {
  font-size: 15px;
  font-weight: 700;
  color: var(--accent-gold-dark);
}

.score-track {
  width: 80px;
  height: 4px;
  background: var(--border);
  border-radius: 2px;
  overflow: hidden;
}

.score-bar {
  height: 100%;
  background: var(--accent-gold);
  border-radius: 2px;
}

/* ── Form Controls ─────────────────────────────────────────────────────────── */
.field-group { display: flex; flex-direction: column; gap: 6px; }

.field-group label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
}

.form-control {
  width: 100%;
  padding: 10px 12px;
  background: var(--bg-card-subtle);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 13px;
  transition: border-color 0.15s;
}

.form-control:focus {
  outline: none;
  border-color: var(--accent-gold);
  box-shadow: 0 0 0 3px rgba(200, 145, 42, 0.12);
}

.form-control option { background: #FFF; color: var(--text-primary); }

/* ── Success Box ───────────────────────────────────────────────────────────── */
.success-box {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
  border-radius: var(--radius-sm);
  background: var(--accent-green-bg);
  border: 1px solid rgba(5, 150, 105, 0.2);
}

.success-header { display: flex; align-items: center; gap: 10px; }

.check-glyph {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-green);
  color: #FFF;
  font-size: 14px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.success-headline { font-size: 14px; font-weight: 700; color: var(--text-primary); }
.success-subline  { font-size: 12px; color: var(--text-secondary); }

.new-item-row {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(0,0,0,0.03);
  border-radius: 6px;
  padding: 10px;
}

.item-thumb {
  width: 56px;
  height: 56px;
  object-fit: contain;
  background: var(--bg-page);
  border-radius: 6px;
  border: 1px solid var(--border);
}

.item-meta { display: flex; flex-direction: column; gap: 4px; }
.item-name { font-size: 14px; font-weight: 600; color: var(--text-primary); }
.item-tags { display: flex; gap: 6px; }

.secondary-btn {
  background: var(--bg-card-subtle);
  border: 1px solid var(--border);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 600;
  padding: 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.15s;
}

.secondary-btn:hover {
  background: var(--accent-gold-bg);
  border-color: var(--accent-gold);
  color: var(--accent-gold-dark);
}

/* ── Recent Items ──────────────────────────────────────────────────────────── */
.recent-wrap { display: flex; flex-direction: column; gap: 8px; margin-top: 6px; }
.recent-list { display: flex; flex-direction: column; gap: 6px; }

.recent-row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-card-subtle);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
}

.recent-row img { width: 36px; height: 36px; object-fit: contain; border-radius: 4px; }
.recent-row span { font-size: 12px; color: var(--text-secondary); }

/* ── Footer ────────────────────────────────────────────────────────────────── */
.bottom-bar {
  text-align: center;
  font-size: 11px;
  color: var(--text-muted);
  padding: 8px;
  border-top: 1px solid var(--border);
}

.hidden { display: none !important; }

/* ═══════════════════════════════════════════════════════════════════════════
   PHASE 7 — EVALUATION ARENA (Light Theme)
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Arena Banner ──────────────────────────────────────────────────────────── */
.arena-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding: 22px 28px;
  background: linear-gradient(135deg, #FFF9EE 0%, #FFFDF7 100%);
  border: 1px solid rgba(200, 145, 42, 0.3);
  border-radius: var(--radius-lg);
  box-shadow: 0 2px 12px rgba(200, 145, 42, 0.10);
  position: relative;
  overflow: hidden;
}

.arena-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    45deg, transparent, transparent 24px,
    rgba(200, 145, 42, 0.04) 24px, rgba(200, 145, 42, 0.04) 25px
  );
  pointer-events: none;
}

.arena-title-wrap {
  display: flex;
  align-items: center;
  gap: 14px;
  position: relative;
}

.arena-icon {
  font-size: 38px;
  filter: drop-shadow(0 2px 8px rgba(200, 145, 42, 0.4));
}

.arena-title {
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--accent-gold-dark);
  line-height: 1;
  margin-bottom: 4px;
}

.arena-sub {
  font-size: 12px;
  color: var(--text-muted);
}

.arena-controls {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
  position: relative;
}

/* ── Eval Buttons ──────────────────────────────────────────────────────────── */
.eval-btn {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 700;
  padding: 9px 18px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  border: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.eval-btn-primary {
  background: var(--accent-gold);
  color: #FFF;
  box-shadow: 0 2px 10px rgba(200, 145, 42, 0.35);
}

.eval-btn-primary:hover {
  background: var(--accent-gold-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(200, 145, 42, 0.45);
}

.eval-btn-primary:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}

.eval-btn-ghost {
  background: var(--bg-card);
  border: 1px solid var(--border);
  color: var(--text-secondary);
}

.eval-btn-ghost:hover {
  border-color: var(--accent-gold);
  color: var(--accent-gold-dark);
  background: var(--accent-gold-bg);
}

/* ── Eval Empty ────────────────────────────────────────────────────────────── */
.eval-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 20px;
  text-align: center;
  gap: 12px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
}

.eval-empty-icon { font-size: 52px; }

.eval-empty h3 {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
}

.eval-empty p {
  font-size: 13px;
  color: var(--text-muted);
  max-width: 380px;
}

/* ── Eval Content ──────────────────────────────────────────────────────────── */
.eval-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ── Scoreboard ────────────────────────────────────────────────────────────── */
.scoreboard {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}

@media (max-width: 1100px) { .scoreboard { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 640px)  { .scoreboard { grid-template-columns: repeat(2, 1fr); } }

.score-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 18px 14px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  position: relative;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all 0.15s ease;
}

.score-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.score-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
}

.score-card--gold::before   { background: var(--accent-gold); }
.score-card--blue::before   { background: var(--accent-blue); }
.score-card--green::before  { background: var(--accent-green); }
.score-card--red::before    { background: var(--accent-red); }
.score-card--purple::before { background: var(--accent-purple); }
.score-card--orange::before { background: var(--accent-orange); }

.score-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: var(--text-muted);
}

.score-value {
  font-family: var(--font-mono);
  font-size: 26px;
  font-weight: 700;
  line-height: 1.2;
}

.score-card--gold   .score-value { color: var(--accent-gold-dark); }
.score-card--blue   .score-value { color: var(--accent-blue); }
.score-card--green  .score-value { color: var(--accent-green); }
.score-card--red    .score-value { color: var(--accent-red); }
.score-card--purple .score-value { color: var(--accent-purple); }
.score-card--orange .score-value { color: var(--accent-orange); }

.score-sublabel {
  font-size: 10px;
  color: var(--text-muted);
  text-align: center;
}

/* ── Eval Mid Grid ─────────────────────────────────────────────────────────── */
.eval-mid-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 16px;
}

@media (max-width: 900px) { .eval-mid-grid { grid-template-columns: 1fr; } }

.eval-card { gap: 14px; }

/* ── Condition Chart ───────────────────────────────────────────────────────── */
.condition-chart {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.chart-legend {
  display: flex;
  gap: 16px;
  margin-bottom: 2px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 600;
}

.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  display: inline-block;
}

.cond-row {
  display: grid;
  grid-template-columns: 120px 1fr 50px 50px;
  align-items: center;
  gap: 10px;
}

.cond-name {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-transform: capitalize;
}

.cond-bar-track {
  background: var(--bg-page);
  border-radius: 4px;
  height: 8px;
  overflow: hidden;
  border: 1px solid var(--border);
}

.cond-bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.cond-bar-fill--top1 { background: var(--accent-gold); }
.cond-bar-fill--top5 { background: var(--accent-blue); opacity: 0.6; }

.cond-pct {
  font-size: 11px;
  font-weight: 700;
  text-align: right;
}

.cond-pct--top1 { color: var(--accent-gold-dark); }
.cond-pct--top5 { color: var(--accent-blue); }

/* ── Progress Arena ────────────────────────────────────────────────────────── */
.progress-arena { display: flex; flex-direction: column; gap: 12px; }

.progress-numbers {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.prog-current {
  font-family: var(--font-mono);
  font-size: 44px;
  font-weight: 700;
  color: var(--accent-gold-dark);
  line-height: 1;
}

.prog-sep { font-size: 24px; color: var(--text-muted); }
.prog-target { font-size: 22px; color: var(--text-muted); }

.progress-track {
  background: var(--bg-page);
  border: 1px solid var(--border);
  border-radius: 8px;
  height: 14px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-gold), #E5A830);
  border-radius: 8px;
  transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

.progress-pct {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-gold-dark);
}

.progress-hint {
  font-size: 11px;
  color: var(--text-muted);
}

.verdict-split {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}

.verdict-track {
  flex: 1;
  display: flex;
  height: 10px;
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid var(--border);
}

.verdict-match-bar   { background: var(--accent-green); height: 100%; transition: width 0.6s ease; }
.verdict-unknown-bar { background: var(--accent-red);   height: 100%; transition: width 0.6s ease; }

.verdict-label {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  white-space: nowrap;
}

.verdict-count { color: var(--text-primary); font-weight: 700; }

.dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }
.dot--green { background: var(--accent-green); }
.dot--red   { background: var(--accent-red); }

/* ── Failures Table ────────────────────────────────────────────────────────── */
.failures-table-wrap { overflow-x: auto; }

.failures-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  min-width: 700px;
}

.failures-table th {
  text-align: left;
  padding: 10px 12px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  border-bottom: 2px solid var(--border);
  background: var(--bg-card-subtle);
  white-space: nowrap;
}

.failures-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text-secondary);
  vertical-align: middle;
}

.failures-table tr:last-child td { border-bottom: none; }

.failures-table tbody tr:hover td {
  background: var(--bg-card-subtle);
}

.failure-thumb {
  width: 44px;
  height: 44px;
  object-fit: cover;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg-page);
}

.tag-condition {
  font-size: 10px;
  background: rgba(124, 58, 237, 0.08);
  border: 1px solid rgba(124, 58, 237, 0.2);
  color: var(--accent-purple);
  padding: 2px 7px;
  border-radius: 4px;
  font-weight: 600;
  white-space: nowrap;
}

.badge-match {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
  background: var(--accent-green-bg);
  border: 1px solid rgba(5, 150, 105, 0.2);
  color: var(--accent-green);
}

.badge-unknown {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
  background: var(--accent-red-bg);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: var(--accent-red);
}

.sim-low  { color: var(--accent-red);   font-weight: 700; }
.sim-mid  { color: var(--accent-orange); font-weight: 700; }
.sim-high { color: var(--accent-green); font-weight: 700; }

.table-empty {
  text-align: center;
  padding: 32px;
  color: var(--text-muted);
}

/* ── Eval Meta ─────────────────────────────────────────────────────────────── */
.eval-meta {
  text-align: center;
  font-size: 11px;
  color: var(--text-muted);
  padding: 4px;
}

