import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.jsx';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

/* ─────────────────────────────────────────────────────────────────────────────
   Thuli — Luxury Jewellery Vision Retrieval & Evaluation
   Design System: Refined Light & Dark Themes
   ───────────────────────────────────────────────────────────────────────────── */

:root {
  --bg-app: #f8fafc;
  --bg-surface: #ffffff;
  --bg-surface-alt: #f1f5f9;
  --bg-surface-hover: #f8fafc;
  --border: #e2e8f0;
  --border-strong: #cbd5e1;
  --border-focus: #d97706;

  --text-main: #0f172a;
  --text-secondary: #475569;
  --text-muted: #94a3b8;

  --primary: #d97706;
  --primary-hover: #b45309;
  --primary-light: #fef3c7;
  --primary-border: #fcd34d;

  --success: #059669;
  --success-bg: #ecfdf5;
  --success-border: #a7f3d0;

  --danger: #dc2626;
  --danger-bg: #fef2f2;
  --danger-border: #fecaca;

  --info: #2563eb;
  --info-bg: #eff6ff;
  --info-border: #bfdbfe;

  --badge-bg: #f1f5f9;
  --badge-text: #334155;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.05);

  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-mono: 'Space Grotesk', monospace;
}

[data-theme="dark"] {
  --bg-app: #0b0f19;
  --bg-surface: #111827;
  --bg-surface-alt: #1a2234;
  --bg-surface-hover: #1f293d;
  --border: #1f2937;
  --border-strong: #374151;
  --border-focus: #f59e0b;

  --text-main: #f9fafb;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;

  --primary: #f59e0b;
  --primary-hover: #fbbf24;
  --primary-light: rgba(245, 158, 11, 0.15);
  --primary-border: rgba(245, 158, 11, 0.35);

  --success: #10b981;
  --success-bg: rgba(16, 185, 129, 0.15);
  --success-border: rgba(16, 185, 129, 0.35);

  --danger: #ef4444;
  --danger-bg: rgba(239, 68, 68, 0.15);
  --danger-border: rgba(239, 68, 68, 0.35);

  --info: #3b82f6;
  --info-bg: rgba(59, 130, 246, 0.15);
  --info-border: rgba(59, 130, 246, 0.35);

  --badge-bg: #1e293b;
  --badge-text: #cbd5e1;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.6);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.7);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-app);
  color: var(--text-main);
  min-height: 100vh;
  line-height: 1.5;
  transition: background-color 0.2s ease, color 0.2s ease;
  overflow-x: hidden;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: var(--bg-app);
}
::-webkit-scrollbar-thumb {
  background: var(--border-strong);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* Layout */
.app-container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 1.5rem 3rem 1.5rem;
}

/* Header */
.app-header {
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(16px);
  background: rgba(255, 255, 255, 0.85);
  border-bottom: 1px solid var(--border);
  padding: 0.85rem 1.5rem;
  margin-bottom: 2rem;
  transition: all 0.2s ease;
}

[data-theme="dark"] .app-header {
  background: rgba(17, 24, 39, 0.85);
}

.header-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.brand-section {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand-logo-icon {
  width: 2.5rem;
  height: 2.5rem;
  background: linear-gradient(135deg, #f59e0b, #d97706, #b45309);
  color: white;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 10px rgba(217, 119, 6, 0.3);
  font-size: 1.25rem;
}

.brand-title {
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.brand-badge {
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--primary-light);
  color: var(--primary);
  border: 1px solid var(--primary-border);
  padding: 0.2rem 0.55rem;
  border-radius: 9999px;
  font-family: var(--font-mono);
}

/* Navigation Tabs */
.nav-tabs {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  background: var(--bg-surface-alt);
  padding: 0.3rem;
  border-radius: 12px;
  border: 1px solid var(--border);
}

.nav-tab-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.55rem 1rem;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  border: none;
  background: transparent;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.nav-tab-btn:hover {
  color: var(--text-main);
  background: rgba(0, 0, 0, 0.04);
}

[data-theme="dark"] .nav-tab-btn:hover {
  background: rgba(255, 255, 255, 0.05);
}

.nav-tab-btn.active {
  background: var(--bg-surface);
  color: var(--text-main);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.icon-btn {
  width: 2.4rem;
  height: 2.4rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  border: 1px solid var(--border);
  background: var(--bg-surface);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.icon-btn:hover {
  color: var(--text-main);
  border-color: var(--border-strong);
  background: var(--bg-surface-hover);
}

/* Common Card */
.ui-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: var(--shadow-sm);
  padding: 1.5rem;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.ui-card:hover {
  border-color: var(--border-strong);
}

.card-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.25rem;
}

.card-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

/* Primary Button */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.25rem;
  background: linear-gradient(135deg, #d97706, #b45309);
  color: #ffffff;
  font-size: 0.925rem;
  font-weight: 600;
  border-radius: 10px;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
  box-shadow: 0 2px 6px rgba(217, 119, 6, 0.25);
  width: 100%;
}

.btn-primary:hover:not(:disabled) {
  background: linear-gradient(135deg, #b45309, #92400e);
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(217, 119, 6, 0.35);
}

.btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.6rem 1rem;
  background: var(--bg-surface-alt);
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 9px;
  border: 1px solid var(--border);
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-secondary:hover:not(:disabled) {
  background: var(--bg-surface-hover);
  color: var(--text-main);
  border-color: var(--border-strong);
}

/* Two Column Grid */
.two-col-grid {
  display: grid;
  grid-template-columns: 460px 1fr;
  gap: 1.5rem;
  align-items: start;
}

@media (max-width: 1024px) {
  .two-col-grid {
    grid-template-columns: 1fr;
  }
}

/* Dropzone */
.dropzone-container {
  border: 2px dashed var(--border-strong);
  border-radius: 14px;
  padding: 2rem 1.5rem;
  text-align: center;
  background: var(--bg-surface-alt);
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
  min-height: 220px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.dropzone-container:hover, .dropzone-container.is-dragover {
  border-color: var(--primary);
  background: var(--primary-light);
}

.drop-icon-box {
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 50%;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
  margin-bottom: 0.75rem;
  box-shadow: var(--shadow-sm);
}

.drop-text-main {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-main);
  margin-bottom: 0.25rem;
}

.drop-text-sub {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.preview-container {
  position: relative;
  width: 100%;
  height: 240px;
  border-radius: 12px;
  overflow: hidden;
  background: #000;
  display: flex;
  align-items: center;
  justify-content: center;
}

.preview-image {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}

.btn-clear-preview {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  background: rgba(0, 0, 0, 0.7);
  color: white;
  border: none;
  border-radius: 50%;
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s ease;
}

.btn-clear-preview:hover {
  background: #dc2626;
}

/* Sample Pills */
.sample-section {
  margin-top: 1.25rem;
}

.sample-title {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.6rem;
  display: block;
}

.sample-pills-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.5rem;
}

.sample-pill {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.15s ease;
  overflow: hidden;
}

.sample-pill:hover {
  border-color: var(--primary);
  background: var(--bg-surface-hover);
  transform: translateY(-1px);
}

.sample-pill img {
  width: 2rem;
  height: 2rem;
  border-radius: 6px;
  object-fit: cover;
  flex-shrink: 0;
}

.sample-pill span {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: capitalize;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Settings sliders */
.settings-box {
  margin-top: 1.25rem;
  padding: 1rem;
  background: var(--bg-surface-alt);
  border-radius: 12px;
  border: 1px solid var(--border);
}

.setting-row {
  margin-bottom: 0.85rem;
}

.setting-row:last-child {
  margin-bottom: 0;
}

.setting-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 0.35rem;
}

.setting-val {
  font-family: var(--font-mono);
  color: var(--primary);
  font-weight: 700;
}

.slider-input {
  width: 100%;
  accent-color: var(--primary);
  cursor: pointer;
}

/* Match / Verdict Banner */
.verdict-banner {
  padding: 1.25rem;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.25rem;
  animation: fadeIn 0.3s ease;
}

.verdict-banner.match {
  background: var(--success-bg);
  border: 1px solid var(--success-border);
}

.verdict-banner.unknown {
  background: var(--danger-bg);
  border: 1px solid var(--danger-border);
}

.verdict-left {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.verdict-badge {
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  padding: 0.35rem 0.75rem;
  border-radius: 8px;
  font-family: var(--font-mono);
}

.verdict-banner.match .verdict-badge {
  background: var(--success);
  color: white;
}

.verdict-banner.unknown .verdict-badge {
  background: var(--danger);
  color: white;
}

.verdict-text-main {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-main);
}

.verdict-text-sub {
  font-size: 0.8rem;
  color: var(--text-secondary);
}

.verdict-metrics {
  display: flex;
  gap: 1.5rem;
}

.verdict-metric-item {
  text-align: right;
}

.verdict-metric-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
  font-weight: 600;
}

.verdict-metric-value {
  font-size: 1.1rem;
  font-weight: 800;
  font-family: var(--font-mono);
  color: var(--text-main);
}

/* Candidate match cards */
.candidates-grid {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.candidate-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.85rem 1rem;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  transition: all 0.15s ease;
}

.candidate-card:hover {
  border-color: var(--border-strong);
  box-shadow: var(--shadow-sm);
  background: var(--bg-surface-hover);
}

.candidate-card.top1 {
  border-color: var(--primary);
  background: var(--primary-light);
}

.rank-circle {
  width: 2.2rem;
  height: 2.2rem;
  border-radius: 50%;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.candidate-card.top1 .rank-circle {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}

.candidate-thumb {
  width: 4rem;
  height: 4rem;
  border-radius: 8px;
  object-fit: cover;
  border: 1px solid var(--border);
  background: #fff;
  flex-shrink: 0;
}

.candidate-info {
  flex: 1;
  min-width: 0;
}

.candidate-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.25rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.candidate-tags {
  display: flex;
  gap: 0.4rem;
  align-items: center;
  flex-wrap: wrap;
}

.tag-badge {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.15rem 0.5rem;
  border-radius: 6px;
  background: var(--badge-bg);
  color: var(--badge-text);
  border: 1px solid var(--border);
  text-transform: capitalize;
}

.tag-id {
  font-family: var(--font-mono);
  font-size: 0.725rem;
  color: var(--text-muted);
}

.candidate-score-block {
  width: 140px;
  text-align: right;
  flex-shrink: 0;
}

.candidate-score-num {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--text-main);
}

.candidate-card.top1 .candidate-score-num {
  color: var(--primary);
}

.score-bar-bg {
  width: 100%;
  height: 6px;
  background: var(--border);
  border-radius: 9999px;
  overflow: hidden;
  margin-top: 0.35rem;
}

.score-bar-fill {
  height: 100%;
  border-radius: 9999px;
  background: linear-gradient(90deg, #d97706, #10b981);
  transition: width 0.4s ease;
}

/* Empty State */
.empty-placeholder {
  padding: 4rem 2rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

.empty-icon-box {
  width: 4rem;
  height: 4rem;
  border-radius: 50%;
  background: var(--bg-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1rem;
  color: var(--text-secondary);
}

.empty-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-secondary);
  margin-bottom: 0.35rem;
}

.empty-desc {
  font-size: 0.875rem;
  max-width: 320px;
}

/* ─────────────────────────────────────────────────────────────────────────────
   Evaluation Dashboard (Phase 7)
   ───────────────────────────────────────────────────────────────────────────── */

.eval-hero-banner {
  background: linear-gradient(135deg, rgba(217, 119, 6, 0.08), rgba(37, 99, 235, 0.06));
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 1.75rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.eval-hero-info h1 {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-main);
  margin-bottom: 0.35rem;
}

.eval-hero-info p {
  color: var(--text-secondary);
  font-size: 0.925rem;
}

.eval-hero-actions {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}

/* KPI Scoreboard */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
  margin-bottom: 2rem;
}

@media (max-width: 1200px) {
  .kpi-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 640px) {
  .kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.kpi-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.25rem 1rem;
  box-shadow: var(--shadow-sm);
  position: relative;
  overflow: hidden;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.kpi-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
}

.kpi-card.gold::before { background: #d97706; }
.kpi-card.blue::before { background: #2563eb; }
.kpi-card.green::before { background: #059669; }
.kpi-card.orange::before { background: #ea580c; }
.kpi-card.purple::before { background: #7c3aed; }
.kpi-card.cyan::before { background: #0891b2; }

.kpi-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}

.kpi-value {
  font-size: 1.75rem;
  font-weight: 800;
  font-family: var(--font-mono);
  color: var(--text-main);
  line-height: 1.1;
}

.kpi-sub {
  font-size: 0.75rem;
  color: var(--text-secondary);
  margin-top: 0.35rem;
}

/* Split layout for charts */
.eval-charts-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 1.5rem;
  margin-bottom: 2rem;
}

@media (max-width: 1024px) {
  .eval-charts-grid {
    grid-template-columns: 1fr;
  }
}

/* Condition accuracy bars */
.condition-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.condition-row {
  display: grid;
  grid-template-columns: 140px 1fr 60px 60px;
  align-items: center;
  gap: 1rem;
  padding: 0.4rem 0;
}

.cond-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: capitalize;
}

.cond-bar-wrap {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.cond-bar-track {
  height: 6px;
  background: var(--border);
  border-radius: 9999px;
  overflow: hidden;
}

.cond-fill-top1 {
  height: 100%;
  background: #d97706;
  border-radius: 9999px;
}

.cond-fill-top5 {
  height: 100%;
  background: #2563eb;
  border-radius: 9999px;
}

.cond-score-num {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 700;
  text-align: right;
}

.cond-score-num.top1 { color: #d97706; }
.cond-score-num.top5 { color: #2563eb; }

/* Progress Gauge */
.progress-card-content {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.progress-track-lg {
  height: 12px;
  background: var(--border);
  border-radius: 9999px;
  overflow: hidden;
}

.progress-fill-lg {
  height: 100%;
  background: linear-gradient(90deg, #d97706, #10b981);
  border-radius: 9999px;
  transition: width 0.5s ease;
}

/* Failures Table */
.failures-table-wrap {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: 12px;
}

.failures-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
  text-align: left;
}

.failures-table th {
  background: var(--bg-surface-alt);
  padding: 0.75rem 1rem;
  font-weight: 700;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}

.failures-table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border);
  color: var(--text-main);
  vertical-align: middle;
}

.failures-table tr:last-child td {
  border-bottom: none;
}

.failures-table tr:hover td {
  background: var(--bg-surface-hover);
}

.fail-thumb {
  width: 44px;
  height: 44px;
  border-radius: 6px;
  object-fit: cover;
  border: 1px solid var(--border);
}

/* Spinner Animation */
.spin-anim {
  animation: spin 1s linear infinite;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

import React, { useState, useEffect, useRef } from 'react';
import {
  Search,
  Sparkles,
  BarChart3,
  PlusCircle,
  Sun,
  Moon,
  Upload,
  X,
  Play,
  RotateCw,
  Download,
  CheckCircle2,
  AlertTriangle,
  Clock,
  Layers,
  ChevronRight,
  Database,
  Sliders,
  ShieldCheck,
  Check,
  AlertCircle
} from 'lucide-react';

export default function App() {
  const [theme, setTheme] = useState(() => {
    return localStorage.getItem('thuli-theme') || 'light';
  });
  const [activeTab, setActiveTab] = useState('search');
  const [stats, setStats] = useState({ total_items: 6157, categories: {} });

  // ── Sync Theme ─────────────────────────────────────────────────────────────
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('thuli-theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'light' ? 'dark' : 'light'));
  };

  // ── Fetch Catalogue Stats ─────────────────────────────────────────────────
  const fetchStats = async () => {
    try {
      const res = await fetch('/api/stats');
      if (res.ok) {
        const data = await res.json();
        setStats(data);
      }
    } catch (err) {
      console.warn('Could not fetch stats:', err);
    }
  };

  useEffect(() => {
    fetchStats();
  }, []);

  // ── Tab 1: Visual Search State ─────────────────────────────────────────────
  const [searchImage, setSearchImage] = useState(null);
  const [searchFile, setSearchFile] = useState(null);
  const [topK, setTopK] = useState(5);
  const [threshold, setThreshold] = useState(0.75);
  const [isSearching, setIsSearching] = useState(false);
  const [searchResults, setSearchResults] = useState(null);
  const [samples, setSamples] = useState([]);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef(null);

  // Load sample items
  useEffect(() => {
    const fetchSamples = async () => {
      try {
        const res = await fetch('/api/samples');
        if (res.ok) {
          const data = await res.json();
          setSamples(data);
        }
      } catch (err) {
        console.warn('Could not load samples:', err);
      }
    };
    fetchSamples();
  }, []);

  const handleSelectFile = (file) => {
    if (!file || !file.type.startsWith('image/')) {
      alert('Please select a valid image file (JPEG, PNG, WebP).');
      return;
    }
    setSearchFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setSearchImage(e.target.result);
      setSearchResults(null);
    };
    reader.readAsDataURL(file);
  };

  const handleClearImage = () => {
    setSearchImage(null);
    setSearchFile(null);
    setSearchResults(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const executeSearch = async (overrideFile = null) => {
    const fileToUse = overrideFile || searchFile;
    if (!fileToUse) return;

    setIsSearching(true);
    const formData = new FormData();
    formData.append('file', fileToUse);
    formData.append('top_k', topK);
    formData.append('threshold', threshold);

    try {
      const res = await fetch('/api/match', {
        method: 'POST',
        body: formData,
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ detail: res.statusText }));
        throw new Error(err.detail || 'Visual search failed.');
      }
      const data = await res.json();
      setSearchResults(data);
    } catch (err) {
      alert('Search Error: ' + err.message);
    } finally {
      setIsSearching(false);
    }
  };

  const handleSampleClick = async (sample) => {
    try {
      const res = await fetch(sample.image_path);
      const blob = await res.blob();
      const file = new File([blob], `${sample.product_id}.jpg`, { type: 'image/jpeg' });
      setSearchFile(file);
      setSearchImage(sample.image_path);
      executeSearch(file);
    } catch (err) {
      console.error('Error with sample:', err);
    }
  };

  // ── Tab 2: Evaluation Arena State ──────────────────────────────────────────
  const [evalMetrics, setEvalMetrics] = useState(null);
  const [isLoadingEval, setIsLoadingEval] = useState(false);
  const [isEvaluating, setIsEvaluating] = useState(false);

  const fetchEvalMetrics = async () => {
    setIsLoadingEval(true);
    try {
      const res = await fetch('/api/evaluation/results');
      if (res.status === 404) {
        setEvalMetrics(null);
      } else if (res.ok) {
        const data = await res.json();
        setEvalMetrics(data.metrics);
      }
    } catch (err) {
      console.warn('Eval results fetch failed:', err);
    } finally {
      setIsLoadingEval(false);
    }
  };

  useEffect(() => {
    if (activeTab === 'eval') {
      fetchEvalMetrics();
    }
  }, [activeTab]);

  const triggerEvaluation = async () => {
    setIsEvaluating(true);
    try {
      const res = await fetch('/api/evaluation/run', { method: 'POST' });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ detail: res.statusText }));
        throw new Error(err.detail || 'Evaluation failed.');
      }
      const data = await res.json();
      setEvalMetrics(data.metrics);
    } catch (err) {
      alert('Evaluation error: ' + err.message);
    } finally {
      setIsEvaluating(false);
    }
  };

  // ── Tab 3: Add Item State ──────────────────────────────────────────────────
  const [addFile, setAddFile] = useState(null);
  const [addImagePreview, setAddImagePreview] = useState(null);
  const [addCategory, setAddCategory] = useState('ring');
  const [addName, setAddName] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [lastAdded, setLastAdded] = useState(null);
  const [recentItems, setRecentItems] = useState([]);
  const addFileInputRef = useRef(null);

  const handleSelectAddFile = (file) => {
    if (!file || !file.type.startsWith('image/')) {
      alert('Please upload an image.');
      return;
    }
    setAddFile(file);
    const reader = new FileReader();
    reader.onload = (e) => setAddImagePreview(e.target.result);
    reader.readAsDataURL(file);
  };

  const handleClearAddImage = () => {
    setAddFile(null);
    setAddImagePreview(null);
    if (addFileInputRef.current) addFileInputRef.current.value = '';
  };

  const handleAddItem = async (e) => {
    e.preventDefault();
    if (!addFile) return;

    setIsAdding(true);
    const formData = new FormData();
    formData.append('file', addFile);
    formData.append('category', addCategory);
    if (addName.trim()) formData.append('product_name', addName.trim());

    try {
      const res = await fetch('/api/catalogue/add', {
        method: 'POST',
        body: formData,
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ detail: res.statusText }));
        throw new Error(err.detail || 'Failed to add item');
      }
      const data = await res.json();
      const itemWithBlob = { ...data, fileBlob: addFile };
      setLastAdded(itemWithBlob);
      setRecentItems(prev => [itemWithBlob, ...prev.slice(0, 4)]);
      fetchStats();

      // Reset form
      handleClearAddImage();
      setAddName('');
    } catch (err) {
      alert('Error adding item: ' + err.message);
    } finally {
      setIsAdding(false);
    }
  };

  const testAddedInSearch = (item) => {
    if (!item?.fileBlob) return;
    setSearchFile(item.fileBlob);
    setSearchImage(item.image_url);
    setActiveTab('search');
    executeSearch(item.fileBlob);
  };

  return (
    <div className="app-wrapper">
      {/* ── Header ───────────────────────────────────────────────────────── */}
      <header className="app-header">
        <div className="header-inner">
          <div className="brand-section">
            <div className="brand-logo-icon">💎</div>
            <div>
              <div className="brand-title">
                THULI
                <span className="brand-badge">
                  {stats.total_items?.toLocaleString() || '6,157'} Items
                </span>
              </div>
            </div>
          </div>

          <nav className="nav-tabs">
            <button
              className={`nav-tab-btn ${activeTab === 'search' ? 'active' : ''}`}
              onClick={() => setActiveTab('search')}
            >
              <Search size={16} />
              <span>Visual Search</span>
            </button>
            <button
              className={`nav-tab-btn ${activeTab === 'eval' ? 'active' : ''}`}
              onClick={() => setActiveTab('eval')}
            >
              <BarChart3 size={16} />
              <span>Evaluation Arena</span>
              {evalMetrics && (
                <span style={{
                  fontSize: '0.7rem',
                  background: 'var(--primary-light)',
                  color: 'var(--primary)',
                  padding: '1px 6px',
                  borderRadius: '999px',
                  fontFamily: 'var(--font-mono)'
                }}>
                  {(evalMetrics.top1_accuracy * 100).toFixed(0)}%
                </span>
              )}
            </button>
            <button
              className={`nav-tab-btn ${activeTab === 'add' ? 'active' : ''}`}
              onClick={() => setActiveTab('add')}
            >
              <PlusCircle size={16} />
              <span>Add Item</span>
            </button>
          </nav>

          <div className="header-actions">
            <button
              className="icon-btn"
              onClick={toggleTheme}
              title={`Switch to ${theme === 'light' ? 'Dark' : 'Light'} theme`}
            >
              {theme === 'light' ? <Moon size={18} /> : <Sun size={18} />}
            </button>
          </div>
        </div>
      </header>

      {/* ── Main Container ───────────────────────────────────────────────── */}
      <main className="app-container">
        {/* VIEW 1: VISUAL SEARCH */}
        {activeTab === 'search' && (
          <div className="two-col-grid">
            {/* Left Column: Query Card */}
            <div className="ui-card">
              <div className="card-title-row">
                <h2 className="card-title">
                  <Sparkles size={18} style={{ color: 'var(--primary)' }} />
                  Query Photograph
                </h2>
                {searchImage && (
                  <button className="btn-secondary" onClick={handleClearImage}>
                    Clear
                  </button>
                )}
              </div>

              {/* Dropzone */}
              {!searchImage ? (
                <div
                  className={`dropzone-container ${isDragging ? 'is-dragover' : ''}`}
                  onDragOver={(e) => {
                    e.preventDefault();
                    setIsDragging(true);
                  }}
                  onDragLeave={() => setIsDragging(false)}
                  onDrop={(e) => {
                    e.preventDefault();
                    setIsDragging(false);
                    if (e.dataTransfer.files?.length > 0) {
                      handleSelectFile(e.dataTransfer.files[0]);
                    }
                  }}
                  onClick={() => fileInputRef.current?.click()}
                >
                  <input
                    type="file"
                    ref={fileInputRef}
                    accept="image/*"
                    style={{ display: 'none' }}
                    onChange={(e) => {
                      if (e.target.files?.length > 0) {
                        handleSelectFile(e.target.files[0]);
                      }
                    }}
                  />
                  <div className="drop-icon-box">
                    <Upload size={24} />
                  </div>
                  <div className="drop-text-main">Click or drop jewellery photo</div>
                  <div className="drop-text-sub">Supports JPEG, PNG, WebP</div>
                </div>
              ) : (
                <div className="preview-container">
                  <img src={searchImage} alt="Query preview" className="preview-image" />
                  <button
                    className="btn-clear-preview"
                    onClick={handleClearImage}
                    title="Remove photo"
                  >
                    <X size={16} />
                  </button>
                </div>
              )}

              {/* Action Button */}
              <div style={{ marginTop: '1.25rem' }}>
                <button
                  className="btn-primary"
                  disabled={!searchFile || isSearching}
                  onClick={() => executeSearch()}
                >
                  {isSearching ? (
                    <>
                      <RotateCw size={18} className="spin-anim" />
                      Retrieving Top Matches...
                    </>
                  ) : (
                    <>
                      <Search size={18} />
                      Find Matching Jewellery
                    </>
                  )}
                </button>
              </div>

              {/* Sample catalogue chips */}
              {samples.length > 0 && (
                <div className="sample-section">
                  <span className="sample-title">Or Try Catalogue Samples:</span>
                  <div className="sample-pills-row">
                    {samples.slice(0, 4).map((sample) => (
                      <div
                        key={sample.product_id}
                        className="sample-pill"
                        onClick={() => handleSampleClick(sample)}
                      >
                        <img src={sample.image_path} alt={sample.product_name} />
                        <span>{sample.category}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Settings Accordion */}
              <div className="settings-box">
                <div className="setting-row">
                  <div className="setting-header">
                    <span>Candidates (Top-K)</span>
                    <span className="setting-val">{topK}</span>
                  </div>
                  <input
                    type="range"
                    min="1"
                    max="10"
                    value={topK}
                    onChange={(e) => setTopK(Number(e.target.value))}
                    className="slider-input"
                  />
                </div>
                <div className="setting-row">
                  <div className="setting-header">
                    <span>Match Threshold (τ)</span>
                    <span className="setting-val">{threshold.toFixed(2)}</span>
                  </div>
                  <input
                    type="range"
                    min="0.50"
                    max="0.95"
                    step="0.01"
                    value={threshold}
                    onChange={(e) => setThreshold(Number(e.target.value))}
                    className="slider-input"
                  />
                </div>
              </div>
            </div>

            {/* Right Column: Results Card */}
            <div className="ui-card">
              <div className="card-title-row">
                <h2 className="card-title">
                  <Layers size={18} style={{ color: 'var(--primary)' }} />
                  Retrieval Candidates
                </h2>
                {searchResults && (
                  <span style={{
                    fontSize: '0.8rem',
                    fontFamily: 'var(--font-mono)',
                    color: 'var(--text-muted)'
                  }}>
                    {searchResults.query_time_ms} ms
                  </span>
                )}
              </div>

              {/* Results or Empty State */}
              {searchResults ? (
                <div>
                  {/* Verdict Banner */}
                  <div
                    className={`verdict-banner ${
                      searchResults.decision === 'MATCH' ? 'match' : 'unknown'
                    }`}
                  >
                    <div className="verdict-left">
                      <span className="verdict-badge">
                        {searchResults.decision === 'MATCH' ? 'MATCH' : 'UNKNOWN'}
                      </span>
                      <div>
                        <div className="verdict-text-main">
                          {searchResults.decision === 'MATCH'
                            ? 'Confident Match Identified'
                            : 'Unknown Jewellery Item'}
                        </div>
                        <div className="verdict-text-sub">
                          {searchResults.decision === 'MATCH'
                            ? `Similarity exceeds threshold ${threshold.toFixed(2)}`
                            : `Similarity ${(searchResults.best_similarity * 100).toFixed(1)}% is below ${threshold.toFixed(2)}`}
                        </div>
                      </div>
                    </div>
                    <div className="verdict-metrics">
                      <div className="verdict-metric-item">
                        <div className="verdict-metric-label">Best Match</div>
                        <div className="verdict-metric-value">
                          {(searchResults.best_similarity * 100).toFixed(1)}%
                        </div>
                      </div>
                      <div className="verdict-metric-item">
                        <div className="verdict-metric-label">Latency</div>
                        <div className="verdict-metric-value">
                          {searchResults.query_time_ms}ms
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Candidates List */}
                  <div className="candidates-grid">
                    {searchResults.results.map((item) => {
                      const simPct = (Math.max(0, Math.min(1, item.similarity)) * 100).toFixed(1);
                      const imgUrl = item.image_url || `/${item.image_path}`;
                      return (
                        <div
                          key={item.product_id}
                          className={`candidate-card ${item.rank === 1 ? 'top1' : ''}`}
                        >
                          <div className="rank-circle">#{item.rank}</div>
                          <img
                            src={imgUrl}
                            alt={item.product_name}
                            className="candidate-thumb"
                            onError={(e) => {
                              e.target.style.display = 'none';
                            }}
                          />
                          <div className="candidate-info">
                            <div className="candidate-title">{item.product_name}</div>
                            <div className="candidate-tags">
                              <span className="tag-badge">{item.category}</span>
                              <span className="tag-id">{item.product_id}</span>
                            </div>
                          </div>
                          <div className="candidate-score-block">
                            <div className="candidate-score-num">{simPct}%</div>
                            <div className="score-bar-bg">
                              <div
                                className="score-bar-fill"
                                style={{ width: `${simPct}%` }}
                              />
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ) : (
                <div className="empty-placeholder">
                  <div className="empty-icon-box">
                    <Search size={32} />
                  </div>
                  <div className="empty-title">No Active Query</div>
                  <div className="empty-desc">
                    Upload a jewellery photo or pick one of the catalogue samples to view matching items.
                  </div>
                </div>
              )}
            </div>
          </div>
        )}

        {/* VIEW 2: EVALUATION ARENA (PHASE 7) */}
        {activeTab === 'eval' && (
          <div>
            {/* Hero Header */}
            <div className="eval-hero-banner">
              <div className="eval-hero-info">
                <h1>Baseline Evaluation Arena</h1>
                <p>
                  Benchmarking CLIP ViT-B/32 against {evalMetrics?.total_images || 39} real-world stumper test cases (angle, blur, lighting, occlusion).
                </p>
              </div>
              <div className="eval-hero-actions">
                <button
                  className="btn-primary"
                  style={{ width: 'auto' }}
                  onClick={triggerEvaluation}
                  disabled={isEvaluating}
                >
                  {isEvaluating ? (
                    <>
                      <RotateCw size={16} className="spin-anim" />
                      Evaluating...
                    </>
                  ) : (
                    <>
                      <Play size={16} />
                      Run Evaluation
                    </>
                  )}
                </button>
                <button
                  className="btn-secondary"
                  onClick={fetchEvalMetrics}
                  disabled={isLoadingEval}
                  title="Refresh metrics"
                >
                  <RotateCw size={16} className={isLoadingEval ? 'spin-anim' : ''} />
                  Refresh
                </button>
                <a
                  href="/api/evaluation/download"
                  download
                  className="btn-secondary"
                  style={{ textDecoration: 'none' }}
                >
                  <Download size={16} />
                  Download CSV
                </a>
              </div>
            </div>

            {/* Dashboard Content */}
            {evalMetrics ? (
              <div>
                {/* KPI Cards */}
                <div className="kpi-grid">
                  <div className="kpi-card gold">
                    <div className="kpi-label">Top-1 Accuracy</div>
                    <div className="kpi-value">
                      {(evalMetrics.top1_accuracy * 100).toFixed(1)}%
                    </div>
                    <div className="kpi-sub">Exact primary match</div>
                  </div>

                  <div className="kpi-card blue">
                    <div className="kpi-label">Top-5 Accuracy</div>
                    <div className="kpi-value">
                      {(evalMetrics.top5_accuracy * 100).toFixed(1)}%
                    </div>
                    <div className="kpi-sub">Found in 5 candidates</div>
                  </div>

                  <div className="kpi-card green">
                    <div className="kpi-label">Match Verdicts</div>
                    <div className="kpi-value">{evalMetrics.match_count}</div>
                    <div className="kpi-sub">≥ 0.75 threshold</div>
                  </div>

                  <div className="kpi-card orange">
                    <div className="kpi-label">Unknown Verdicts</div>
                    <div className="kpi-value">{evalMetrics.unknown_count}</div>
                    <div className="kpi-sub">&lt; 0.75 threshold</div>
                  </div>

                  <div className="kpi-card purple">
                    <div className="kpi-label">Median Latency</div>
                    <div className="kpi-value">{evalMetrics.median_latency_ms}ms</div>
                    <div className="kpi-sub">P50 inference time</div>
                  </div>

                  <div className="kpi-card cyan">
                    <div className="kpi-label">P95 Latency</div>
                    <div className="kpi-value">{evalMetrics.p95_latency_ms}ms</div>
                    <div className="kpi-sub">95th percentile</div>
                  </div>
                </div>

                {/* Grid: Condition breakdown & Progress */}
                <div className="eval-charts-grid">
                  {/* Left: Per-Condition Accuracy */}
                  <div className="ui-card">
                    <div className="card-title-row">
                      <h3 className="card-title">
                        <BarChart3 size={18} style={{ color: 'var(--primary)' }} />
                        Accuracy by Real-World Condition
                      </h3>
                      <div style={{ display: 'flex', gap: '1rem', fontSize: '0.75rem' }}>
                        <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                          <span style={{ width: 8, height: 8, borderRadius: 2, background: '#d97706' }}></span>
                          Top-1
                        </span>
                        <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                          <span style={{ width: 8, height: 8, borderRadius: 2, background: '#2563eb' }}></span>
                          Top-5
                        </span>
                      </div>
                    </div>

                    <div className="condition-list">
                      {Object.entries(evalMetrics.per_condition || {})
                        .sort((a, b) => b[1].top1_accuracy - a[1].top1_accuracy)
                        .map(([cond, vals]) => {
                          const t1 = (vals.top1_accuracy * 100).toFixed(0);
                          const t5 = (vals.top5_accuracy * 100).toFixed(0);
                          return (
                            <div key={cond} className="condition-row">
                              <span className="cond-name">{cond.replace(/_/g, ' ')}</span>
                              <div className="cond-bar-wrap">
                                <div className="cond-bar-track">
                                  <div className="cond-fill-top1" style={{ width: `${t1}%` }} />
                                </div>
                                <div className="cond-bar-track">
                                  <div className="cond-fill-top5" style={{ width: `${t5}%` }} />
                                </div>
                              </div>
                              <span className="cond-score-num top1">{t1}%</span>
                              <span className="cond-score-num top5">{t5}%</span>
                            </div>
                          );
                        })}
                    </div>
                  </div>

                  {/* Right: Dataset Milestone & Verdict Ratio */}
                  <div className="ui-card">
                    <div className="card-title-row">
                      <h3 className="card-title">
                        <Database size={18} style={{ color: 'var(--primary)' }} />
                        Stumper Dataset Progress
                      </h3>
                      <span className="brand-badge">
                        {evalMetrics.dataset_progress?.current || 39} / 100
                      </span>
                    </div>

                    <div className="progress-card-content">
                      <div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem', fontSize: '0.85rem' }}>
                          <span style={{ color: 'var(--text-secondary)' }}>Collected Test Images</span>
                          <strong style={{ fontFamily: 'var(--font-mono)' }}>
                            {evalMetrics.dataset_progress?.pct || 39}%
                          </strong>
                        </div>
                        <div className="progress-track-lg">
                          <div
                            className="progress-fill-lg"
                            style={{ width: `${evalMetrics.dataset_progress?.pct || 39}%` }}
                          />
                        </div>
                      </div>

                      <div style={{
                        padding: '1rem',
                        background: 'var(--bg-surface-alt)',
                        borderRadius: '12px',
                        border: '1px solid var(--border)'
                      }}>
                        <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginBottom: '0.5rem' }}>
                          DECISION SPLIT (0.75 THRESHOLD)
                        </div>
                        <div style={{ display: 'flex', height: '10px', borderRadius: '5px', overflow: 'hidden', marginBottom: '0.5rem' }}>
                          <div
                            style={{
                              width: `${(evalMetrics.match_count / evalMetrics.total_images) * 100}%`,
                              background: '#059669'
                            }}
                          />
                          <div
                            style={{
                              width: `${(evalMetrics.unknown_count / evalMetrics.total_images) * 100}%`,
                              background: '#dc2626'
                            }}
                          />
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.8rem', fontFamily: 'var(--font-mono)' }}>
                          <span style={{ color: '#059669', fontWeight: 700 }}>
                            {evalMetrics.match_count} MATCH
                          </span>
                          <span style={{ color: '#dc2626', fontWeight: 700 }}>
                            {evalMetrics.unknown_count} UNKNOWN
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Failures Table */}
                <div className="ui-card">
                  <div className="card-title-row">
                    <h3 className="card-title">
                      <AlertTriangle size={18} style={{ color: '#dc2626' }} />
                      Failure Analysis & Hard Cases ({evalMetrics.worst_failures?.length || 0})
                    </h3>
                  </div>

                  <div className="failures-table-wrap">
                    <table className="failures-table">
                      <thead>
                        <tr>
                          <th>Preview</th>
                          <th>Image ID</th>
                          <th>Ground Truth</th>
                          <th>Top-1 Prediction</th>
                          <th>Similarity</th>
                          <th>GT Rank</th>
                          <th>Condition</th>
                          <th>Verdict</th>
                        </tr>
                      </thead>
                      <tbody>
                        {evalMetrics.worst_failures?.length > 0 ? (
                          evalMetrics.worst_failures.map((f) => (
                            <tr key={f.image_id}>
                              <td>
                                <img
                                  src={`/evaluation/images/${f.image_id}.jpeg`}
                                  alt={f.image_id}
                                  className="fail-thumb"
                                  onError={(e) => {
                                    e.target.style.display = 'none';
                                  }}
                                />
                              </td>
                              <td style={{ fontFamily: 'var(--font-mono)', color: 'var(--text-muted)' }}>
                                {f.image_id}
                              </td>
                              <td>
                                <span className="tag-badge">{f.ground_truth}</span>
                              </td>
                              <td>
                                <span
                                  className="tag-badge"
                                  style={{ background: 'var(--danger-bg)', color: 'var(--danger)', borderColor: 'var(--danger-border)' }}
                                >
                                  {f.top1_category || '—'}
                                </span>
                              </td>
                              <td style={{ fontFamily: 'var(--font-mono)', fontWeight: 700 }}>
                                {f.top1_similarity?.toFixed(4)}
                              </td>
                              <td style={{ color: 'var(--text-muted)' }}>
                                {f.gt_rank > 0 ? `#${f.gt_rank}` : 'Not in Top-5'}
                              </td>
                              <td>
                                <span className="tag-badge">
                                  {f.failure_condition?.replace(/_/g, ' ')}
                                </span>
                              </td>
                              <td>
                                <span
                                  style={{
                                    fontSize: '0.75rem',
                                    fontWeight: 700,
                                    padding: '2px 8px',
                                    borderRadius: '6px',
                                    background: f.decision === 'MATCH' ? 'var(--success-bg)' : 'var(--danger-bg)',
                                    color: f.decision === 'MATCH' ? 'var(--success)' : 'var(--danger)'
                                  }}
                                >
                                  {f.decision}
                                </span>
                              </td>
                            </tr>
                          ))
                        ) : (
                          <tr>
                            <td colSpan={8} style={{ textAlign: 'center', padding: '2rem' }}>
                              🎉 No failures found!
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            ) : (
              <div className="ui-card" style={{ textAlign: 'center', padding: '4rem 2rem' }}>
                <div className="empty-icon-box" style={{ margin: '0 auto 1rem auto' }}>
                  <BarChart3 size={32} />
                </div>
                <h3 style={{ fontSize: '1.2rem', fontWeight: 700, marginBottom: '0.5rem' }}>
                  Arena Results Pending
                </h3>
                <p style={{ color: 'var(--text-secondary)', marginBottom: '1.5rem', maxWidth: '400px', margin: '0 auto 1.5rem auto' }}>
                  Click below to evaluate CLIP ViT-B/32 against all 39 real-world stumper test cases.
                </p>
                <button
                  className="btn-primary"
                  style={{ width: 'auto', display: 'inline-flex' }}
                  onClick={triggerEvaluation}
                  disabled={isEvaluating}
                >
                  {isEvaluating ? (
                    <>
                      <RotateCw size={16} className="spin-anim" />
                      Evaluating...
                    </>
                  ) : (
                    <>
                      <Play size={16} />
                      Run Evaluation Now
                    </>
                  )}
                </button>
              </div>
            )}
          </div>
        )}

        {/* VIEW 3: ADD ITEM */}
        {activeTab === 'add' && (
          <div className="two-col-grid">
            {/* Form */}
            <div className="ui-card">
              <div className="card-title-row">
                <h2 className="card-title">
                  <PlusCircle size={18} style={{ color: 'var(--primary)' }} />
                  Add Catalogue Item
                </h2>
              </div>

              <form onSubmit={handleAddItem}>
                {/* Dropzone */}
                {!addImagePreview ? (
                  <div
                    className="dropzone-container"
                    onClick={() => addFileInputRef.current?.click()}
                  >
                    <input
                      type="file"
                      ref={addFileInputRef}
                      accept="image/*"
                      style={{ display: 'none' }}
                      onChange={(e) => {
                        if (e.target.files?.length > 0) {
                          handleSelectAddFile(e.target.files[0]);
                        }
                      }}
                    />
                    <div className="drop-icon-box">
                      <Upload size={24} />
                    </div>
                    <div className="drop-text-main">Upload jewellery photograph</div>
                    <div className="drop-text-sub">JPEG, PNG, WebP</div>
                  </div>
                ) : (
                  <div className="preview-container">
                    <img src={addImagePreview} alt="Upload preview" className="preview-image" />
                    <button
                      type="button"
                      className="btn-clear-preview"
                      onClick={handleClearAddImage}
                    >
                      <X size={16} />
                    </button>
                  </div>
                )}

                <div style={{ marginTop: '1.25rem' }}>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 600, marginBottom: '0.4rem' }}>
                    Category
                  </label>
                  <select
                    value={addCategory}
                    onChange={(e) => setAddCategory(e.target.value)}
                    style={{
                      width: '100%',
                      padding: '0.65rem 0.85rem',
                      borderRadius: '8px',
                      border: '1px solid var(--border)',
                      background: 'var(--bg-surface)',
                      color: 'var(--text-main)',
                      fontSize: '0.9rem'
                    }}
                  >
                    <option value="ring">Ring</option>
                    <option value="necklace">Necklace</option>
                    <option value="earrings">Earrings</option>
                    <option value="bracelet">Bracelet</option>
                    <option value="bangle">Bangle</option>
                    <option value="pendant">Pendant</option>
                  </select>
                </div>

                <div style={{ marginTop: '1rem' }}>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 600, marginBottom: '0.4rem' }}>
                    Product Name (Optional)
                  </label>
                  <input
                    type="text"
                    value={addName}
                    onChange={(e) => setAddName(e.target.value)}
                    placeholder="e.g. 18K Diamond Solitaire Ring"
                    style={{
                      width: '100%',
                      padding: '0.65rem 0.85rem',
                      borderRadius: '8px',
                      border: '1px solid var(--border)',
                      background: 'var(--bg-surface)',
                      color: 'var(--text-main)',
                      fontSize: '0.9rem'
                    }}
                  />
                </div>

                <div style={{ marginTop: '1.5rem' }}>
                  <button
                    type="submit"
                    className="btn-primary"
                    disabled={!addFile || isAdding}
                  >
                    {isAdding ? (
                      <>
                        <RotateCw size={18} className="spin-anim" />
                        Encoding Vector & Adding to FAISS...
                      </>
                    ) : (
                      <>
                        <PlusCircle size={18} />
                        Add to Catalogue & Index
                      </>
                    )}
                  </button>
                </div>
              </form>
            </div>

            {/* Right: Last Added Item & Quick Test */}
            <div className="ui-card">
              <div className="card-title-row">
                <h2 className="card-title">
                  <CheckCircle2 size={18} style={{ color: 'var(--success)' }} />
                  Indexing Status
                </h2>
              </div>

              {lastAdded ? (
                <div>
                  <div style={{
                    padding: '1.25rem',
                    background: 'var(--success-bg)',
                    border: '1px solid var(--success-border)',
                    borderRadius: '12px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '1rem',
                    marginBottom: '1.5rem'
                  }}>
                    <img
                      src={lastAdded.image_url}
                      alt={lastAdded.product_name}
                      style={{ width: '60px', height: '60px', borderRadius: '8px', objectFit: 'cover' }}
                    />
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 700, color: 'var(--text-main)' }}>
                        {lastAdded.product_name}
                      </div>
                      <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>
                        Category: {lastAdded.category} • ID: {lastAdded.product_id}
                      </div>
                      <div style={{ fontSize: '0.75rem', color: 'var(--success)', fontWeight: 600, marginTop: '2px' }}>
                        ✓ 512-d CLIP vector indexed into FAISS
                      </div>
                    </div>
                  </div>

                  <button
                    className="btn-secondary"
                    style={{ width: '100%', marginBottom: '1.5rem' }}
                    onClick={() => testAddedInSearch(lastAdded)}
                  >
                    <Search size={16} />
                    Test this Item in Visual Search
                  </button>

                  {recentItems.length > 1 && (
                    <div>
                      <h4 style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: '0.75rem' }}>
                        RECENTLY ADDED
                      </h4>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                        {recentItems.slice(1).map((item) => (
                          <div
                            key={item.product_id}
                            style={{
                              display: 'flex',
                              alignItems: 'center',
                              gap: '0.75rem',
                              padding: '0.5rem',
                              borderRadius: '8px',
                              border: '1px solid var(--border)'
                            }}
                          >
                            <img
                              src={item.image_url}
                              alt={item.product_name}
                              style={{ width: '36px', height: '36px', borderRadius: '6px', objectFit: 'cover' }}
                            />
                            <div style={{ flex: 1, minWidth: 0 }}>
                              <div style={{ fontSize: '0.85rem', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                {item.product_name}
                              </div>
                              <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                                {item.category} • {item.product_id}
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              ) : (
                <div className="empty-placeholder">
                  <div className="empty-icon-box">
                    <Database size={32} />
                  </div>
                  <div className="empty-title">Ready to Index</div>
                  <div className="empty-desc">
                    Upload a photograph to instantly extract its CLIP ViT-B/32 embedding and insert it into the FAISS vector index.
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

