/* Results Table Filters & Badges */
.table-filter-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.table-filter-tabs {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  background: var(--bg-surface-alt);
  padding: 0.25rem;
  border-radius: 10px;
  border: 1px solid var(--border);
}

.filter-tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.85rem;
  font-size: 0.825rem;
  font-weight: 600;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.filter-tab-btn:hover {
  color: var(--text-main);
  background: rgba(0, 0, 0, 0.04);
}

[data-theme="dark"] .filter-tab-btn:hover {
  background: rgba(255, 255, 255, 0.05);
}

.filter-tab-btn.active {
  background: var(--bg-surface);
  color: var(--text-main);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
}

.filter-tab-btn.active.filter-correct {
  color: var(--success);
  border-color: var(--success-border);
}

.filter-tab-btn.active.filter-wrong {
  color: var(--danger);
  border-color: var(--danger-border);
}

.filter-search-box {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.4rem 0.75rem;
  font-size: 0.85rem;
}

.filter-search-input {
  border: none;
  background: transparent;
  color: var(--text-main);
  font-size: 0.85rem;
  outline: none;
  width: 140px;
}

.filter-select {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.4rem 0.75rem;
  font-size: 0.825rem;
  color: var(--text-main);
  outline: none;
  cursor: pointer;
}

/* Outcome badges */
.badge-correct {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.65rem;
  border-radius: 6px;
  background: var(--success-bg);
  color: var(--success);
  border: 1px solid var(--success-border);
  font-family: var(--font-mono);
}

.badge-wrong {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.65rem;
  border-radius: 6px;
  background: var(--danger-bg);
  color: var(--danger);
  border: 1px solid var(--danger-border);
  font-family: var(--font-mono);
}

.row-correct {
  background: rgba(5, 150, 105, 0.02);
}

.row-wrong {
  background: rgba(220, 38, 38, 0.03);
}

.failures-table tr.row-correct:hover td {
  background: rgba(5, 150, 105, 0.05);
}

.failures-table tr.row-wrong:hover td {
  background: rgba(220, 38, 38, 0.06);
}

.prediction-match-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-weight: 700;
  color: var(--success);
}

.prediction-mismatch-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-weight: 700;
  color: var(--danger);
}

.rank-badge-top1 {
  color: var(--success);
  font-weight: 700;
  font-family: var(--font-mono);
}

.rank-badge-top5 {
  color: var(--info);
  font-weight: 600;
  font-family: var(--font-mono);
}

.rank-badge-miss {
  color: var(--text-muted);
  font-family: var(--font-mono);
}

